    'یه سوییچ «پخش صدای دوبله» تو Popup هست؛ خاموشش کنی، تشخیص زندهٔ Gemini فقط زیرنویس نشون می‌ده، بدون صدای دوبله. مناسب استریم‌های زنده.':'There is a “Play dubbed audio” switch in the Popup. Turn it off and Gemini live recognition shows subtitles only, without dubbed audio. Useful for live streams.',
    'کاراکتر ترجمه‌شده و ثانیهٔ دوبله رو نشون می‌ده و با نرخی که خودت وارد می‌کنی هزینه رو تخمین می‌زنه.':'Shows translated characters and dubbing seconds, then estimates cost using the rate you enter.',
    'علاوه بر WAV، حالا می‌تونی دوبله رو با حجمی تا ۴ برابر کمتر دانلود کنی.':'In addition to WAV, you can now download dubbing at up to 4× smaller file size.',
    'علاوه بر یوتیوب، به‌همراه یه لایهٔ اضافی استخراج کپشن (خوندن پنل Transcript خودِ یوتیوب) برای ویدیوهایی که جور دیگه‌ای کپشنشون پیدا نمی‌شه.':'In addition to YouTube, with an extra caption-extraction layer that reads YouTube’s own Transcript panel when captions cannot be found another way.',
    'یک دکمه برای حذف کامل کلید‌ها، تنظیمات، آمار و حافظهٔ ترجمه.':'One button to permanently delete keys, settings, statistics, and translation memory.',
    'مدیریت سرویس سفارشی از Popup به Options منتقل شد؛ درخواست اجازهٔ دسترسی دیگه Popup رو نمی‌بنده و متنی که تایپ کردی از دست نمی‌ره.':'Custom service management moved from Popup to Options; permission requests no longer block the Popup or erase typed text.',
    'STT و TTS پیش‌فرض به ارزون‌ترین گزینهٔ موجود تغییر کرد (قابل تغییر در Options).':'Default STT and TTS were changed to the lowest-cost available options (changeable in Options).',
    'رفع باگ قطع‌شدن ترجمه‌های طولانی وسط کار (سقف توکن اصلاح شد).':'Fixed long translations stopping mid-way (token limit corrected).','رفع ناهماهنگی توگل زیرنویس بین Popup و پخش‌کننده.':'Fixed subtitle toggle mismatch between the Popup and player.',
    'حالا فقط برای همون یک دامنه‌ای که خودت وارد می‌کنی اجازه می‌گیره، نه کل اینترنت.':'It now requests permission only for the single domain you enter, not the whole internet.','دسترسی افزونه از «همهٔ سایت‌ها» به دامنه‌های واقعاً موردنیاز محدود شد.':'Extension access is limited from “all sites” to only the domains actually required.',
    'اگه از ایران وصل می‌شی و Gemini جواب نمی‌ده: این مسدودی از سمت گوگل و به‌خاطر تحریمه، نه چیزی که این افزونه بتونه حلش کنه. تنها راه، یه VPN سیستمیه که کل ترافیک مرورگر رو عوض کنه، ریسک ToS داره، تضمینی هم نیست.':'If you are connecting from Iran and Gemini does not respond, the block is imposed by Google due to sanctions, not something this extension can fix. A system-wide VPN is the only workaround that changes all browser traffic, with ToS risks and no guarantee.',
    'اگه با نسخهٔ قبل مشکلی داشتی، این نسخه از پایه اون بخش‌ها رو دوباره نوشته. اگه بازم مشکلی دیدی از دکمهٔ گزارش داخل Popup بگو.':'If you had issues with the previous version, those parts have been rewritten from the ground up. If you still see a problem, use the report button in the Popup.',
    // r18 additions: learning, AI pages, live class and dubbing
