    "یک ایده یا مفهوم از ویدیو را برای دوستی که آن را ندیده توضیح بده.": "Explain one idea or concept from the video to a friend who has not seen it.",
    "هم‌صحبت": "Conversation partner",
    "چت، نوشتن و نقش‌آفرینی به حساب کاربری نیاز دارند. امکانات ویدیویی برای ده ویدیوی اول بدون ورود رایگان است. برای ادامه وارد شو (روی آیکون افزونه بزن ← ورود).": "Chat, writing and roleplay need an account. Video features are free for the first 10 videos without sign-in. To continue, sign in (click the extension icon → Sign in).",
    
