    "از دکمهٔ بزرگ وسط شروع کن": "ابدأ بالزر الكبير في الوسط",
    
    "سرویس ترجمه رو از تب «ترجمه» عوض کن": "غيّر خدمة الترجمة من تبويب «الترجمة»",
    "اگه خواستی، از تب «ترجمه» می‌تونی سرویس هوش مصنوعی (Gemini/OpenRouter/OpenAI) و مدلش رو انتخاب کنی. در حالت پیش‌فرض خودش بهترین گزینه رو انتخاب می‌کنه.": "إن أردت، يمكنك من تبويب «الترجمة» اختيار خدمة الذكاء الاصطناعي (Gemini/OpenRouter/OpenAI) ونموذجها. في الوضع التلقائي تختار Subify الخيار المناسب.",
