    "مثلاً model-name": "مثلاً model-name",
    "کد مدل را دقیقاً از سایت سرویس کپی کن. اگر سرویس دکمه «دریافت مدل‌ها» دارد، می‌توانی از همان استفاده کنی.": "انسخ معرّف النموذج تماماً من موقع الخدمة. وإذا كان للخدمة زر «جلب النماذج» فيمكنك استخدامه.",
