    "تست کلیدهای Gemini، OpenRouter و OpenAI داخل Popup انجام می‌شود. این صفحه فقط تست مسیر Live و صدای دوبله را نگه می‌دارد.": "تُجرى اختبارات مفاتيح Gemini وOpenRouter وOpenAI داخل النافذة المنبثقة. تحتفظ هذه الصفحة باختبار مسار Live وصوت الدبلجة فقط.",
