    "هنوز تستی اجرا نشده است.": "لم يُجرَ أي اختبار بعد.",
    "آمار مصرف و برآورد هزینه": "الاستهلاك وتقدير التكلفة",
    "اعداد زیر مصرف واقعیِ همین افزونه‌ست. برای برآورد هزینه، نرخ هر سرویس رو خودت جلوش وارد کن، چون قیمت‌ها بین سرویس‌ها/مدل‌ها فرق داره و مدام تغییر می‌کنه، اینجا هیچ عددی حدس زده نمی‌شه؛ فقط مصرف تو در نرخی که خودت می‌دی ضرب می‌شه.": "الأرقام أدناه هي الاستهلاك الفعلي لهذه الإضافة. لتقدير التكلفة أدخل سعر كل خدمة بنفسك، لأن الأسعار تختلف بين الخدمات والنماذج وتتغير باستمرار، لذلك لا يُخمَّن أي رقم هنا؛ يُضرب استهلاكك فقط في السعر الذي تحدده.",
    "واحد نرخ‌گذاری": "وحدة التسعير",
    "هر ۱۰۰۰ کاراکتر": "لكل 1000 حرف",
    "هر ۱ میلیون توکن (تخمینی)": "لكل مليون رمز (تقديري)",
    "هنوز هیچ ترجمه یا دوبله‌ای ثبت نشده.": "لم تُسجَّل أي ترجمة أو دبلجة بعد.",
    "یادگیری هنگام تماشا": "التعلّم أثناء المشاهدة",
    "این تنظیمات روی زیرنویس سایت‌های پشتیبانی‌شده اعمال می‌شن. لغت‌های ذخیره‌شده طبق وضعیت مرورشان هایلایت می‌شن؛ «تازه» یعنی هنوز یک‌بار هم مرور نشده.": "تُطبَّق هذه الإعدادات على الترجمات في المواقع المدعومة. تُبرز الكلمات المحفوظة حسب حالة مراجعتها؛ «جديدة» تعني أنها لم تُراجَع ولو مرة واحدة.",
