    "برای این بخش هیچ کلید هوش مصنوعی ذخیره نشده. از آیکون Subify، تب «کلیدها» یک کلید را ذخیره کن: Gemini، OpenRouter، OpenAI یا Custom API.": "لا يوجد مفتاح ذكاء اصطناعي محفوظ لهذا القسم. من أيقونة Subify افتح تبويب «المفاتيح» واحفظ مفتاحًا واحدًا: Gemini أو OpenRouter أو OpenAI أو Custom API.",
