    "من مبین‌ام، سازنده Subify": "أنا مبين، صانع Subify",
    "داستان Subify از زمانی شروع شد که داشتم زبان اسپانیایی یاد می‌گرفتم و برای یادگیری و آمادگی کنکور، خیلی از ویدیوهای آموزشی YouTube رو می‌دیدم. یه مشکل بزرگ داشتم؛ زبانم هنوز اون‌قدر خوب نبود که بتونم همه ویدیوها رو راحت بفهمم": "بدأت قصة Subify حين كنت أتعلم الإسبانية، وكنت أشاهد الكثير من فيديوهات YouTube التعليمية للدراسة والاستعداد لامتحان القبول الجامعي. كانت لدي مشكلة كبيرة: لغتي لم تكن جيدة بما يكفي بعد لأتابع كل الفيديوهات بسهولة.",
    "خیلی از ویدیوها ترجمه فارسی نداشتن، بعضی از زیرنویس‌ها هم قابل‌فهم نبودن و پیدا کردن دوبله مناسب تقریباً غیرممکن بود. برای فهمیدن هر جمله باید ویدیو رو متوقف می‌کردم، متن رو کپی می‌کردم، می‌رفتم سراغ مترجم یا یه ابزار هوش مصنوعی و بعد دوباره برمی‌گشتم به ویدیو. چند دقیقه بعد هم همین داستان تکرار می‌شد!": "لم تكن لكثير من الفيديوهات ترجمة فارسية، وكانت بعض الترجمات المصاحبة صعبة الفهم، وكان العثور على دبلجة جيدة شبه مستحيل. لفهم كل جملة كان عليّ أن أوقف الفيديو، وأنسخ النص، وأذهب إلى مترجم أو أداة ذكاء اصطناعي، ثم أعود إلى الفيديو. وبعد دقائق قليلة كان الأمر يتكرر!",
    "به‌جای اینکه روی یادگیری تمرکز کنم، مدام بین ویدیو و ابزارهای مختلف جابه‌جا می‌شدم. خلاصه اینکه یادگیری خودش تبدیل شده بود به یه پروژه جداگانه": "بدلاً من أن أركز على التعلم، كنت أتنقل باستمرار بين الفيديو وأدوات مختلفة. باختصار، تحوّل التعلم نفسه إلى مشروع مستقل قائم بذاته.",
    "اما چیزی که باعث شد این موضوع رو جدی‌تر دنبال کنم، هستی بود. اون هم با همین مشکل روبه‌رو بود و وقتی دیدم این چالش فقط برای من نیست، بیشتر به این فکر کردم که چرا نباید راه ساده‌تری برای فهمیدن ویدیوها وجود داشته باشه؟": "ما جعلني أتابع هذا الأمر بجدية أكبر هو هستي. فقد واجهت المشكلة نفسها، وحين رأيت أن هذا التحدي ليس لي وحدي، بدأت أتساءل لماذا لا يكون هناك طريق أسهل لفهم الفيديوهات؟",
    "همین شد که تصمیم گرفتم Subify رو بسازم": "وهكذا قررت أن أبني Subify.",
    "راستش اون موقع فکر نمی‌کردم این ایده تا این اندازه بزرگ بشه. هدفم این بود که ابزاری داشته باشم که ترجمه و فهمیدن ویدیوها رو راحت‌تر کنه، بدون اینکه لازم باشه برای هر جمله سراغ چند ابزار مختلف برم": "والحق أنني حينها لم أكن أتوقع أن تكبر هذه الفكرة إلى هذا الحد. كان هدفي أن أملك أداة تجعل ترجمة الفيديوهات وفهمها أسهل، دون الحاجة إلى التنقل بين عدة أدوات لكل جملة.",
    "از هستی هم واقعاً ممنونم، چون تجربه مشترکمون نقش مهمی در جدی شدن این ایده داشت. شاید بدون اون هم یه روزی به فکر ساخت چنین ابزاری می‌افتادم، اما دوست دارم همیشه یادم بمونه که این مسیر چطور شروع شد": "أنا ممتن حقاً لهستي، لأن تجربتنا المشتركة لعبت دوراً مهماً في جعل هذه الفكرة جدية. ربما كنت سأفكر يوماً ما في بناء أداة كهذه حتى بدونها، لكنني أريد أن أتذكر دائماً كيف بدأ هذا الطريق.",
    "ولی داستان همین‌جا تموم نشد": "لكن القصة لم تنتهِ هنا.",
    "هرچی بیشتر روی Subify کار کردم، بیشتر متوجه شدم که مشکل فقط ترجمه ویدیو نیست": "كلما عملت أكثر على Subify، أدركت أكثر أن المشكلة ليست في ترجمة الفيديو وحدها.",
    "کسی که زبان یاد می‌گیره، ممکنه به توضیح گرامر نیاز داشته باشه. یکی دیگه دنبال معنی یه کلمه‌ست، یکی می‌خواد با هوش مصنوعی صحبت کنه و سؤال بپرسه و یکی هم ترجیح می‌ده به‌جای خوندن زیرنویس، ویدیو رو به زبان خودش بشنوه": "قد يحتاج من يتعلم لغة إلى شرح للقواعد. وآخر يبحث عن معنى كلمة، وآخر يريد أن يتحدث مع الذكاء الاصطناعي ويطرح أسئلته، وآخر يفضّل أن يسمع الفيديو بلغته بدلاً من قراءة الترجمات.",
    "از طرفی، هوش مصنوعی هر روز امکانات جدیدتری در اختیارمون می‌ذاره و به نظرم حیف بود Subify رو به یه ابزار ساده برای ترجمه زیرنویس محدود کنم": "ومن جهة أخرى، يمنحنا الذكاء الاصطناعي إمكانيات جديدة كل يوم، ورأيت أن حصر Subify في أداة بسيطة لترجمة النصوص المصاحبة للفيديو سيكون هدراً.",
    "برای همین، کم‌کم شروع کردم به گسترش ایده اولیه و ساخت قابلیت‌های جدید. چیزی که با یه نیاز شخصی شروع شده بود، به محصولی تبدیل شد که امروز بخش‌های مختلفی از یادگیری زبان، ترجمه و تعامل با هوش مصنوعی رو کنار هم قرار می‌ده": "ولهذا بدأت شيئاً فشيئاً في توسيع الفكرة الأولى وبناء ميزات جديدة. ما بدأ بحاجة شخصية تحوّل إلى منتج يجمع اليوم أجزاءً مختلفة من تعلم اللغات والترجمة والتفاعل مع الذكاء الاصطناعي.",
    "الان Subify فقط برای ترجمه ویدیو نیست. توی وب‌اپلیکیشنش می‌تونی با هوش مصنوعی چت کنی، گرامر زبان یاد بگیری، معنی و ترجمه لغات رو پیدا کنی، از ابزارهای یادگیری زبان استفاده کنی و با کمک قابلیت‌های ترجمه و دوبله هوش مصنوعی، محتوای ویدیویی رو راحت‌تر دنبال کنی": "لم يعد Subify مخصصاً لترجمة الفيديو فقط. في تطبيق الويب يمكنك التحدث مع الذكاء الاصطناعي، وتعلّم القواعد، والبحث عن معنى الكلمات وترجمتها، واستخدام أدوات تعلم اللغات، ومتابعة محتوى الفيديو بسهولة أكبر بمساعدة ترجمة الذكاء الاصطناعي ودبلجته.",
