    "از همون اول هم نمی‌خواستم Subify فقط به YouTube محدود بمونه. هدفم این بوده که تجربه استفاده از محتوای چندزبانه رو در پلتفرم‌های مختلف ساده‌تر کنم؛ از ویدیوهای آموزشی و دوره‌های آنلاین گرفته تا محتوای سرگرمی و چیزهایی که هر روز توی اینترنت می‌بینیم": "ومنذ البداية لم أرد لـ Subify أن يقتصر على YouTube. كان هدفي أن أجعل استخدام المحتوى متعدد اللغات أسهل على منصات مختلفة، من الفيديوهات التعليمية والدورات الإلكترونية إلى المحتوى الترفيهي وكل ما نراه يومياً على الإنترنت.",
    "البته ساختن چنین محصولی مسیر ساده‌ای نیست. از توسعه و طراحی گرفته تا کار با مدل‌های هوش مصنوعی، پیدا کردن راه‌حل‌های بهتر و بهتر کردن تجربه کاربر، هنوز کلی چیز برای یاد گرفتن و بهتر کردن وجود داره": "طبعاً، بناء منتج كهذا ليس طريقاً سهلاً. من التطوير والتصميم إلى العمل مع نماذج الذكاء الاصطناعي، وإيجاد حلول أفضل وتحسين تجربة المستخدم، ما زال هناك الكثير لأتعلمه وأحسّنه.",
