    "وقتی به این موضوع فکر می‌کنم، می‌بینم آدم‌های زیادی در سراسر دنیا به محتوایی دسترسی دارن که نمی‌تونن به‌خوبی ازش استفاده کنن، فقط به این دلیل که به زبان دیگه‌ایه": "حين أفكر في هذا، أرى أن كثيراً من الناس في أنحاء العالم يمكنهم الوصول إلى محتوى لا يستطيعون الاستفادة منه جيداً، لسبب واحد فقط: أنه بلغة أخرى.",
    "ممکنه یه نفر بخواد از یه دوره آموزشی چیزی یاد بگیره، یکی دنبال یادگیری یه زبان جدید باشه و یکی دیگه فقط بخواد فیلم یا ویدیوی موردعلاقه‌ش رو بدون دردسر بفهمه": "قد يريد شخص أن يتعلم شيئاً من دورة تدريبية، وقد يتعلم آخر لغة جديدة، ويريد ثالث ببساطة أن يفهم فيلمه أو فيديوه المفضل دون عناء.",
