    "برای من، Subify فقط یه پروژه نرم‌افزاری نیست؛ محصولیه که از یه مشکل واقعی شروع شده و می‌خوام با توسعه و بهتر کردنش، به افراد بیشتری کمک کنم": "بالنسبة لي، Subify ليس مجرد مشروع برمجي. إنه منتج انطلق من مشكلة حقيقية، ومن خلال تطويره وتحسينه أريد أن أساعد عدداً أكبر من الناس.",
    "شاید اولش فقط می‌خواستم خودم راحت‌تر زبان یاد بگیرم، اما حالا هدفم اینه که آدم‌های بیشتری بتونن از محتوایی استفاده کنن که قبلاً به خاطر زبان براشون سخت یا حتی غیرقابل‌دسترس بوده": "في البداية أردت فقط أن أتعلم اللغات بسهولة أكبر، أما الآن فهدفي أن يستطيع عدد أكبر من الناس استخدام محتوى كان صعباً عليهم، بل غير متاح لهم أحياناً، بسبب اللغة.",
