    "کلید Gemini رو بگیر (رایگان، حدود ۳ دقیقه)": "Consigue una clave de Gemini (gratis, unos 3 minutos)","روی Create API key بزن. اگه پرسید پروژه می‌خوای، یه پروژهٔ جدید انتخاب کن.": "Pulsa Create API key. Si pide un proyecto, elige uno nuevo.","کلید رو کپی کن و توی کادر Gemini بالا بذار.": "Copia la clave y pégala en el campo Gemini de arriba.","«ذخیره کلیدها» رو بزن.": "Pulsa «Guardar claves».","OpenRouter و OpenAI اختیاری‌ان. اگه کلید داری، همون کادرها رو پر کن.": "OpenRouter y OpenAI son opcionales. Si tienes sus claves, rellena sus campos.","وضعیت ورودت و پشتیبانی اینجاست. بدون ورود هم افزونه کار می‌کنه.": "Aquí ves tu inicio de sesión y el soporte. La extensión funciona sin iniciar sesión.","صدای اصلی ویدیو": "Volumen del video original",
    "دکمهٔ Subify رو توی نوار پلیر یوتیوب، کنار بقیهٔ دکمه‌ها پیدا می‌کنی. از همون‌جا زیرنویس ترجمه‌شده رو روشن یا خاموش کن. اگه ندیدیش، صفحه رو یه بار تازه کن.": "Encontrarás el botón de Subify en la barra del reproductor de YouTube, junto a los demás botones. Activa o desactiva los subtítulos traducidos desde ahí. Si no lo ves, recarga la página una vez.",
