    "آمار مصرف و برآورد هزینه": "Uso y estimación de costos",
    "اعداد زیر مصرف واقعیِ همین افزونه‌ست. برای برآورد هزینه، نرخ هر سرویس رو خودت جلوش وارد کن، چون قیمت‌ها بین سرویس‌ها/مدل‌ها فرق داره و مدام تغییر می‌کنه، اینجا هیچ عددی حدس زده نمی‌شه؛ فقط مصرف تو در نرخی که خودت می‌دی ضرب می‌شه.": "Las cifras siguientes son el uso real de esta extensión. Para estimar el costo, introduce tú la tarifa de cada servicio: los precios varían entre servicios y modelos y cambian con el tiempo, así que aquí no se adivina ningún número; solo se multiplica tu uso por la tarifa que indiques.",
