    "هنوز هیچ ترجمه یا دوبله‌ای ثبت نشده.": "Aún no se ha registrado ninguna traducción ni doblaje.",
    "یادگیری هنگام تماشا": "Aprender mientras ves",
    "این تنظیمات روی زیرنویس سایت‌های پشتیبانی‌شده اعمال می‌شن. لغت‌های ذخیره‌شده طبق وضعیت مرورشان هایلایت می‌شن؛ «تازه» یعنی هنوز یک‌بار هم مرور نشده.": "Estos ajustes se aplican a los subtítulos de los sitios compatibles. Las palabras guardadas se resaltan según su estado de repaso; «Nueva» significa que aún no se ha repasado ni una vez.",
