    "همهٔ اعداد زیر از داده‌های ذخیره‌شدهٔ همین دستگاه خوانده می‌شن و چیزی تخمین زده نمی‌شه. زمان تماشای ویدیو اندازه‌گیری نمی‌شه، پس نشان داده نمی‌شه.": "Todos los números siguientes se leen de los datos guardados en este dispositivo y de las traducciones. Nada se estima. El tiempo de visualización del video no se mide, por eso no se muestra.",
