    "حریم خصوصی و داده‌ها": "Privacidad y datos",
    "کلیدهای API و تمام تنظیمات فقط روی همین دستگاه (Storage محلی مرورگر) ذخیره می‌شن و جز به همون سرویسی که خودت انتخاب کردی (Gemini/OpenRouter/OpenAI/Custom) به‌جای دیگه‌ای ارسال نمی‌شن. جزئیات کامل در فایل PRIVACY.md همراه افزونه.": "Las claves API y todos los ajustes se guardan solo en este dispositivo (almacenamiento local del navegador) y solo se envían al servicio que elijas (Gemini/OpenRouter/OpenAI/Custom). Los detalles completos están en el archivo PRIVACY.md incluido con la extensión.",
    "پاک‌کردن کامل داده‌ها": "Borrar todos los datos",
    "این کار کلیدهای API، تنظیمات، آمار مصرف، دیکشنری و حافظهٔ ترجمهٔ ذخیره‌شده روی این دستگاه رو برای همیشه پاک می‌کنه، قابل بازگشت نیست.": "Esto borra de forma permanente las claves API, los ajustes, las estadísticas de uso, el diccionario y la memoria de traducción guardada en este dispositivo. No se puede deshacer.",
