    "یک جملهٔ ویدیو را گوش بده، با صدای خودت تکرار کن و بازخورد بگیر.": "Escucha una frase del video, repítela con tu voz y recibe comentarios.",
    "یک متن کوتاه به زبان ویدیو بنویس. اصلاح، بازنویسی طبیعی، تخمین سطح و چند نکته می‌گیری.": "Escribe un texto corto en el idioma del video. Recibirás correcciones, una reescritura natural, una estimación de nivel y algunos consejos.",
    "یک موقعیت را انتخاب کن و به زبان ویدیو گفت‌وگو کن. هر وقت خواستی، گزارش پایان گفت‌وگو را بگیر.": "Elige una escena y habla en el idioma del video. Pide el informe final cuando quieras.",
