    "هم‌صحبت": "Interlocutor",
    "چت، نوشتن و نقش‌آفرینی به حساب کاربری نیاز دارند. امکانات ویدیویی برای ده ویدیوی اول بدون ورود رایگان است. برای ادامه وارد شو (روی آیکون افزونه بزن ← ورود).": "El chat, la escritura y el juego de rol necesitan una cuenta. Las funciones de vídeo son gratis para los primeros 10 vídeos sin iniciar sesión. Para continuar, inicia sesión (haz clic en el icono de la extensión → Iniciar sesión).",
    
