    "تست کلیدهای Gemini، OpenRouter و OpenAI داخل Popup انجام می‌شود. این صفحه فقط تست مسیر Live و صدای دوبله را نگه می‌دارد.": "Gemini, OpenRouter ve OpenAI anahtar testleri açılır pencerede yapılır. Bu sayfa yalnızca Live yolu ve seslendirme sesi testlerini içerir.",
