    "هنوز تستی اجرا نشده است.": "Henüz test çalıştırılmadı.",
    "آمار مصرف و برآورد هزینه": "Kullanım ve maliyet tahmini",
    "اعداد زیر مصرف واقعیِ همین افزونه‌ست. برای برآورد هزینه، نرخ هر سرویس رو خودت جلوش وارد کن، چون قیمت‌ها بین سرویس‌ها/مدل‌ها فرق داره و مدام تغییر می‌کنه، اینجا هیچ عددی حدس زده نمی‌شه؛ فقط مصرف تو در نرخی که خودت می‌دی ضرب می‌شه.": "Aşağıdaki sayılar bu eklentinin gerçek kullanımıdır. Maliyet tahmini için her servisin birim fiyatını kendin gir; fiyatlar servis ve modellere göre değişir ve zamanla güncellenir, bu yüzden burada hiçbir sayı tahmin edilmez; yalnızca kullanımın senin girdiğin fiyatla çarpılır.",
    "واحد نرخ‌گذاری": "Fiyat birimi",
