    "هر ۱ میلیون توکن (تخمینی)": "Milyon token başına (tahmini)",
    "هنوز هیچ ترجمه یا دوبله‌ای ثبت نشده.": "Henüz kayıtlı bir çeviri veya seslendirme yok.",
    "یادگیری هنگام تماشا": "İzlerken öğren",
    "این تنظیمات روی زیرنویس سایت‌های پشتیبانی‌شده اعمال می‌شن. لغت‌های ذخیره‌شده طبق وضعیت مرورشان هایلایت می‌شن؛ «تازه» یعنی هنوز یک‌بار هم مرور نشده.": "Bu ayarlar desteklenen sitelerdeki altyazılara uygulanır. Kayıtlı kelimeler tekrar durumlarına göre vurgulanır; «Yeni», henüz bir kez bile tekrar edilmediği anlamına gelir.",
