    "همهٔ اعداد زیر از داده‌های ذخیره‌شدهٔ همین دستگاه خوانده می‌شن و چیزی تخمین زده نمی‌شه. زمان تماشای ویدیو اندازه‌گیری نمی‌شه، پس نشان داده نمی‌شه.": "Aşağıdaki tüm sayılar bu cihazda kayıtlı verilerden ve çevirilerden okunur. Hiçbir şey tahmin edilmez. Video izleme süresi ölçülmez, bu yüzden gösterilmez.",
    "زبان‌های لغت‌ها": "Kelime dilleri",
