    "کلیدهای API و تمام تنظیمات فقط روی همین دستگاه (Storage محلی مرورگر) ذخیره می‌شن و جز به همون سرویسی که خودت انتخاب کردی (Gemini/OpenRouter/OpenAI/Custom) به‌جای دیگه‌ای ارسال نمی‌شن. جزئیات کامل در فایل PRIVACY.md همراه افزونه.": "API anahtarları ve tüm ayarlar yalnızca bu cihazda (tarayıcının yerel depolaması) saklanır ve yalnızca seçtiğin servise (Gemini/OpenRouter/OpenAI/Custom) gönderilir. Tüm ayrıntılar eklentiyle gelen PRIVACY.md dosyasındadır.",
    "پاک‌کردن کامل داده‌ها": "Tüm verileri sil",
    "این کار کلیدهای API، تنظیمات، آمار مصرف، دیکشنری و حافظهٔ ترجمهٔ ذخیره‌شده روی این دستگاه رو برای همیشه پاک می‌کنه، قابل بازگشت نیست.": "Bu işlem API anahtarlarını, ayarları, kullanım istatistiklerini, sözlüğü ve bu cihazda kayıtlı çeviri belleğini kalıcı olarak siler. Geri alınamaz.",
