    "عیب‌یابی و گزارش": "Diagnostic et rapport",
    "تست کلیدهای Gemini، OpenRouter و OpenAI داخل Popup انجام می‌شود. این صفحه فقط تست مسیر Live و صدای دوبله را نگه می‌دارد.": "Les tests des clés Gemini, OpenRouter et OpenAI se font dans la fenêtre contextuelle. Cette page ne garde que les tests du chemin Live et de l’audio de doublage.",
    "تست Live دوبله": "Tester le Live du doublage",
