    "هنوز تستی اجرا نشده است.": "Aucun test n’a encore été lancé.",
    "آمار مصرف و برآورد هزینه": "Utilisation et estimation des coûts",
    "اعداد زیر مصرف واقعیِ همین افزونه‌ست. برای برآورد هزینه، نرخ هر سرویس رو خودت جلوش وارد کن، چون قیمت‌ها بین سرویس‌ها/مدل‌ها فرق داره و مدام تغییر می‌کنه، اینجا هیچ عددی حدس زده نمی‌شه؛ فقط مصرف تو در نرخی که خودت می‌دی ضرب می‌شه.": "Les chiffres ci-dessous correspondent à l’utilisation réelle de cette extension. Pour estimer le coût, saisissez vous-même le tarif de chaque service : les prix varient selon les services et les modèles et changent avec le temps, aucun chiffre n’est donc deviné ici ; seule votre utilisation est multipliée par le tarif que vous indiquez.",
