    "هنوز هیچ ترجمه یا دوبله‌ای ثبت نشده.": "Aucune traduction ni aucun doublage n’a encore été enregistré.",
    "یادگیری هنگام تماشا": "Apprendre en regardant",
    "این تنظیمات روی زیرنویس سایت‌های پشتیبانی‌شده اعمال می‌شن. لغت‌های ذخیره‌شده طبق وضعیت مرورشان هایلایت می‌شن؛ «تازه» یعنی هنوز یک‌بار هم مرور نشده.": "Ces réglages s’appliquent aux sous-titres des sites pris en charge. Les mots enregistrés sont surlignés selon leur statut de révision ; « Nouveau » signifie qu’ils n’ont pas encore été révisés une seule fois.",
