    "همهٔ اعداد زیر از داده‌های ذخیره‌شدهٔ همین دستگاه خوانده می‌شن و چیزی تخمین زده نمی‌شه. زمان تماشای ویدیو اندازه‌گیری نمی‌شه، پس نشان داده نمی‌شه.": "Tous les chiffres ci-dessous sont lus depuis les données enregistrées sur cet appareil et les traductions. Rien n’est estimé. La durée de visionnage n’est pas mesurée, donc elle n’est pas affichée.",
