    "آخرین لغت‌های ذخیره‌شده": "Derniers mots enregistrés",
    "حریم خصوصی و داده‌ها": "Confidentialité et données",
    "کلیدهای API و تمام تنظیمات فقط روی همین دستگاه (Storage محلی مرورگر) ذخیره می‌شن و جز به همون سرویسی که خودت انتخاب کردی (Gemini/OpenRouter/OpenAI/Custom) به‌جای دیگه‌ای ارسال نمی‌شن. جزئیات کامل در فایل PRIVACY.md همراه افزونه.": "Les clés API et tous les réglages sont enregistrés uniquement sur cet appareil (stockage local du navigateur) et envoyés uniquement au service que vous choisissez (Gemini/OpenRouter/OpenAI/Custom). Les détails figurent dans le fichier PRIVACY.md fourni avec l’extension.",
    "پاک‌کردن کامل داده‌ها": "Supprimer toutes les données",
    "این کار کلیدهای API، تنظیمات، آمار مصرف، دیکشنری و حافظهٔ ترجمهٔ ذخیره‌شده روی این دستگاه رو برای همیشه پاک می‌کنه، قابل بازگشت نیست.": "Cela supprime définitivement les clés API, les réglages, les statistiques d’utilisation, le dictionnaire et la mémoire de traduction enregistrés sur cet appareil. Cette action est irréversible.",
