    "تست کلیدهای Gemini، OpenRouter و OpenAI داخل Popup انجام می‌شود. این صفحه فقط تست مسیر Live و صدای دوبله را نگه می‌دارد.": "Die Tests der Schlüssel für Gemini, OpenRouter und OpenAI laufen im Popup. Diese Seite enthält nur Tests des Live-Pfads und des Synchronisationstons.",
