    "هنوز تستی اجرا نشده است.": "Noch kein Test ausgeführt.",
    "آمار مصرف و برآورد هزینه": "Nutzung & Kostenschätzung",
    "اعداد زیر مصرف واقعیِ همین افزونه‌ست. برای برآورد هزینه، نرخ هر سرویس رو خودت جلوش وارد کن، چون قیمت‌ها بین سرویس‌ها/مدل‌ها فرق داره و مدام تغییر می‌کنه، اینجا هیچ عددی حدس زده نمی‌شه؛ فقط مصرف تو در نرخی که خودت می‌دی ضرب می‌شه.": "Die Zahlen unten sind die tatsächliche Nutzung dieser Erweiterung. Für eine Kostenschätzung gib den Preis jedes Dienstes selbst ein: Preise unterscheiden sich je Dienst und Modell und ändern sich laufend, daher wird hier nichts geschätzt, deine Nutzung wird nur mit dem von dir eingegebenen Preis multipliziert.",
