    "هر ۱ میلیون توکن (تخمینی)": "Pro 1 Mio. Token (geschätzt)",
    "هنوز هیچ ترجمه یا دوبله‌ای ثبت نشده.": "Noch keine Übersetzung oder Synchronisation erfasst.",
    "یادگیری هنگام تماشا": "Beim Schauen lernen",
    "این تنظیمات روی زیرنویس سایت‌های پشتیبانی‌شده اعمال می‌شن. لغت‌های ذخیره‌شده طبق وضعیت مرورشان هایلایت می‌شن؛ «تازه» یعنی هنوز یک‌بار هم مرور نشده.": "Diese Einstellungen gelten für Untertitel auf unterstützten Websites. Gespeicherte Wörter werden nach Wiederholungsstatus hervorgehoben; „Neu“ bedeutet, dass sie noch nicht einmal wiederholt wurden.",
