    "همهٔ اعداد زیر از داده‌های ذخیره‌شدهٔ همین دستگاه خوانده می‌شن و چیزی تخمین زده نمی‌شه. زمان تماشای ویدیو اندازه‌گیری نمی‌شه، پس نشان داده نمی‌شه.": "Alle Zahlen unten stammen aus den auf diesem Gerät gespeicherten Daten und Übersetzungen. Nichts wird geschätzt. Die Videoschauzeit wird nicht gemessen und daher nicht angezeigt.",
