    "کلیدهای API و تمام تنظیمات فقط روی همین دستگاه (Storage محلی مرورگر) ذخیره می‌شن و جز به همون سرویسی که خودت انتخاب کردی (Gemini/OpenRouter/OpenAI/Custom) به‌جای دیگه‌ای ارسال نمی‌شن. جزئیات کامل در فایل PRIVACY.md همراه افزونه.": "API-Schlüssel und alle Einstellungen werden nur auf diesem Gerät (lokaler Browserspeicher) gespeichert und nur an den von dir gewählten Dienst (Gemini/OpenRouter/OpenAI/Custom) gesendet. Details stehen in der Datei PRIVACY.md der Erweiterung.",
    "پاک‌کردن کامل داده‌ها": "Alle Daten löschen",
