    "چت، نوشتن و نقش‌آفرینی به حساب کاربری نیاز دارند. امکانات ویدیویی برای ده ویدیوی اول بدون ورود رایگان است. برای ادامه وارد شو (روی آیکون افزونه بزن ← ورود).": "Chat, Schreiben und Rollenspiel brauchen ein Konto. Videofunktionen sind für die ersten 10 Videos ohne Anmeldung kostenlos. Melde dich an, um weiterzumachen (Erweiterungssymbol anklicken → Anmelden).",
    
