    es: { "لغت‌هایی را که ذخیره کرده‌ای مرور کن. هر کارت را بر اساس یادآوری‌ات جواب بده تا مرور بعدی به‌موقع بیاید. کارت‌ها روی همین مرورگر ذخیره می‌شوند.": "Repasa las palabras que guardaste. Responde cada tarjeta según cuánto la recordabas; la siguiente revisión llega en el momento justo. Las tarjetas se guardan en este navegador.", "صحنه‌های ترجمه‌شدهٔ ویدیوی در حال پخش را در یک برگه جمع کن. هر صحنه زمان، جملهٔ اصلی و ترجمه‌اش را دارد و روی همین مرورگر می‌ماند.": "Reúne en un tablero las escenas traducidas del vídeo que estás viendo. Cada escena tiene su tiempo, la frase original y su traducción, y se queda en este navegador." },
    tr: { "لغت‌هایی را که ذخیره کرده‌ای مرور کن. هر کارت را بر اساس یادآوری‌ات جواب بده تا مرور بعدی به‌موقع بیاید. کارت‌ها روی همین مرورگر ذخیره می‌شوند.": "Kaydettiğin kelimeleri tekrar et. Her kartı ne kadar hatırladığına göre yanıtla; bir sonraki tekrar tam zamanında gelir. Kartlar bu tarayıcıda saklanır.", "صحنه‌های ترجمه‌شدهٔ ویدیوی در حال پخش را در یک برگه جمع کن. هر صحنه زمان، جملهٔ اصلی و ترجمه‌اش را دارد و روی همین مرورگر می‌ماند.": "İzlediğin videonun çevrilmiş sahnelerini tek bir panoda topla. Her sahnenin zamanı, orijinal cümlesi ve çevirisi vardır ve bu tarayıcıda kalır." },
    fr: { "لغت‌هایی را که ذخیره کرده‌ای مرور کن. هر کارت را بر اساس یادآوری‌ات جواب بده تا مرور بعدی به‌موقع بیاید. کارت‌ها روی همین مرورگر ذخیره می‌شوند.": "Révisez les mots que vous avez enregistrés. Répondez à chaque carte selon votre mémoire ; la révision suivante arrive au bon moment. Les cartes sont enregistrées dans ce navigateur.", "صحنه‌های ترجمه‌شدهٔ ویدیوی در حال پخش را در یک برگه جمع کن. هر صحنه زمان، جملهٔ اصلی و ترجمه‌اش را دارد و روی همین مرورگر می‌ماند.": "Rassemblez dans un tableau les scènes traduites de la vidéo que vous regardez. Chaque scène a son heure, la phrase d’origine et sa traduction, et reste dans ce navigateur." },
    de: { "لغت‌هایی را که ذخیره کرده‌ای مرور کن. هر کارت را بر اساس یادآوری‌ات جواب بده تا مرور بعدی به‌موقع بیاید. کارت‌ها روی همین مرورگر ذخیره می‌شوند.": "Wiederhole die gespeicherten Wörter. Beantworte jede Karte danach, wie gut du dich erinnert hast; die nächste Wiederholung kommt zur richtigen Zeit. Die Karten werden in diesem Browser gespeichert.", "صحنه‌های ترجمه‌شدهٔ ویدیوی در حال پخش را در یک برگه جمع کن. هر صحنه زمان، جملهٔ اصلی و ترجمه‌اش را دارد و روی همین مرورگر می‌ماند.": "Sammle die übersetzten Szenen des Videos, das du gerade ansiehst, auf einer Tafel. Jede Szene hat ihre Zeit, den Originalsatz und die Übersetzung und bleibt in diesem Browser." },
