window.SubifyUI?.register({"en":{"تغییرات مهم Subify lite":"Important Subify lite updates","نسخه جدید آماده است. اینجا مهم‌ترین قابلیت‌ها، پلتفرم‌های پشتیبانی‌شده و تغییرات ظاهری و فنی را یک‌جا می‌بینی.":"The new version is ready. Here you can see the main features, supported platforms, and interface and technical changes in one place.","پلتفرم‌های آموزشی":"Learning platforms","این صفحه فقط برای نمایش تغییرات مهم نسخه است. بعد از مطالعه، روی «متوجه شدم» بزن تا دوباره در شروع مرورگر نمایش داده نشود.":"This page shows the main changes in this version. After reading, click “Got it” so it is not shown again when the browser starts.","متوجه شدم":"Got it","این نسخه: ۲.۹.۴۱":"This version: 2.9.41","صفحهٔ یادگیری:":"Learn page:","کنترل زبان دیگر روی متن بالای صفحه نمی‌افتد و عنوان و توضیح کامل دیده می‌شوند.":"The language control no longer covers the text at the top, so the title and full description are visible.","پشتیبانی:":"Support:","دکمهٔ «پشتیبانی» در پنجرهٔ تازه‌ها به صفحهٔ تماس Subify می‌رود.":"The “Support” button in the what’s-new window now opens the Subify contact page.","نسخهٔ ۲.۹.۴۰":"Version 2.9.40","سری روزانه در پاپ‌آپ:":"Daily streak in the popup:","پاپ‌آپ نشان می‌دهد چند روز پشت‌هم کار کرده‌ای و امروز چند دقیقه از هدفت را رفته‌ای. با زدن روی هدف می‌توانی ۵، ۱۰ یا ۲۰ دقیقه انتخاب کنی. فقط روی همین دستگاه ذخیره می‌شود.":"The popup shows how many days in a row you have worked and today’s minutes against your goal. Tap the goal to choose 5, 10 or 20 minutes. It is stored on this device only.","زبان رابط کاربری در ۷ زبان:":"Interface in 7 languages:","پاپ‌آپ، تنظیمات، حساب، صفحهٔ یادگیری و صفحه‌های هوش مصنوعی به فارسی، انگلیسی، عربی، اسپانیایی، ترکی، فرانسوی و آلمانی ترجمه شده‌اند. جهت متن هم با زبان تغییر می‌کند.":"The popup, settings, account, the Learn page and the AI pages are translated into Persian, English, Arabic, Spanish, Turkish, French and German. The text direction changes with the language too.","تنظیمات ساده‌تر:":"Simpler settings:","صفحهٔ تنظیمات حالا در پنج بخش است: خانه، ترجمه و دوبله، یادگیری، کلیدها و سرویس‌ها، حساب و پشتیبانی. هر چیز فقط یک جا آمده است.":"The settings page now has five sections: Home, Translate and dub, Learning, Keys and services, and Account and support. Each item appears in one place only.","تازه‌های این نسخه در تنظیمات:":"What's new in settings:","بار اول که تنظیمات را باز کنی، همین توضیح‌ها را در یک پنجرهٔ کوتاه می‌بینی. برای هر نسخه فقط یک بار نشان داده می‌شود.":"The first time you open settings after an update, you see these notes in a short window. It appears once per version.","صفحه‌های هوش مصنوعی:":"AI pages:","هدر و چیدمان گفت‌وگو، خلاصه، نقش‌آفرینی، نگارش و تمرین تلفظ با بقیهٔ صفحه‌ها یکدست شده و در زبان‌های چپ‌به‌راست و راست‌به‌چپ درست چیده می‌شوند.":"The header and layout of Chat, Summary, Roleplay, Write and Pronunciation now match the other pages and are aligned correctly in both left-to-right and right-to-left languages.","اعداد و متن‌ها:":"Numbers and text:","در زبان‌های غیرفارسی عددها لاتین نشان داده می‌شوند و متن‌های نیمه‌فارسی دیگر در رابط کاربری دیده نمی‌شوند.":"In non-Persian languages, numbers are shown in Latin digits, and mixed Persian text no longer appears in the interface.","حساب و ریست ماهانه:":"Account and monthly reset:","زمان بازنشانی ماهانهٔ سهمیه با قالب تاریخ و ساعت همان زبان نشان داده می‌شود، نه عدد خام.":"The monthly quota reset time is shown in your language’s date and time format, not as a raw number.","نسخهٔ ۲.۹.۳۹":"Version 2.9.39","ورود با نام کاربری و رمز:":"Sign in with a username and password:","حساب را با نام کاربری و رمز بساز یا وارد شو (ایمیل اختیاری است). ورود با Google، GitHub یا LinkedIn هم هست.":"Create an account with a username and password (an email is optional), or sign in with Google, GitHub or LinkedIn.","یک کلمه را بزن تا مکث شود:":"Tap a word to pause:","در حالت یادگیری، زدن روی یک کلمهٔ زیرنویس ویدیو را متوقف می‌کند تا معنی‌اش را بخوانی. با بستن معنی، پخش ادامه پیدا می‌کند.":"In a learning mode, tapping a subtitle word pauses the video so you can read its meaning. Closing the meaning resumes playback.","کارت نقل‌قول با لینک:":"Quote card with a link:","کارت نقل‌قولی که از یادگیری ساخته می‌شود حالا لینک همان لحظهٔ ویدیوی یوتیوب را دارد. لینک هنگام ساخت کارت کپی می‌شود.":"A quote card made from Learn now includes a link to the same moment of the YouTube video. The link is copied when the card is made.","نسخهٔ ۲.۹.۳۰: یادگیری و Storyboard":"Version 2.9.30: Learn and Storyboard","بخش جدا با دو مسیر:":"A separate section with two entries:","زیر «یادگیری و Storyboard» توی پاپ‌آپ دو مورد هست: «یادگیری لغت» برای مرور لغت‌های ذخیره‌شده، و «Storyboard» برای دیدن صحنه‌های ترجمه‌شده. هر کدام یک توضیح کوتاه دارد و با یک کلیک باز می‌شود.":"Under “Learn and Storyboard” in the popup there are two entries: “Learn words” to review saved words, and “Storyboard” to see translated scenes. Each has a short note and opens with one click.","همین دو ابزار از وب‌اپ هم:":"The same two tools in the web app:","کارت «یادگیری و Storyboard» توی خانه و زیر بخش حساب کاربری در تنظیمات هست، پس لازم نیست حتماً از پلیر یا پاپ‌آپ بروی.":"The Learn and Storyboard card is on Home and under your account in Settings, so you do not need to go through the player or the popup.","خروجی Anki از یادگیری لغت:":"Anki export from Learn:","لغت‌های ذخیره‌شده با معنی و جمله، به فایل متنی جدا می‌روند که Anki بدون تبدیل وارد می‌کند.":"Saved words with their meaning and sentence go to a separate text file that Anki imports without conversion.","Storyboard با ترتیب زمان:":"Storyboard in time order:","هر صحنه با شمارهٔ ترتیب و زمان شروع نشان داده می‌شود، جملهٔ اصلی بالا و ترجمه زیر آن می‌آید و در حالت روشن و تیره یکسان دیده می‌شود.":"Each scene shows its number and start time, the original line on top and the translation below, and it looks the same in light and dark mode.","Google Meet و زیرنویس زنده":"Google Meet and live subtitles","زیرنویس در Google Meet:":"Subtitles in Google Meet:","وقتی دوبلهٔ زنده را در Google Meet روشن می‌کنی، زیرنویس هم نشان داده می‌شود. این قابلیت فعلاً فقط در Chrome است، چون Firefox ضبط زندهٔ صدای جلسه را ندارد.":"When you turn on live dubbing in Google Meet, subtitles appear too. For now this works only in Chrome, because Firefox cannot capture the live audio of a meeting.","توقف هم‌زمان صدا و زیرنویس:":"Audio and subtitles stop together:","وقتی دوبلهٔ زنده را متوقف می‌کنی، صدای دوبله و زیرنویس با هم می‌ایستند و با هم ادامه پیدا می‌کنند، تا از هم جدا نشوند.":"When you stop live dubbing, the dubbed audio and the subtitles stop together and resume together, so they do not drift apart.","Google Meet در فهرست پلتفرم‌ها:":"Google Meet in the platform list:","Google Meet به پلتفرم‌های پشتیبانی‌شده اضافه شد.":"Google Meet was added to the supported platforms.","رابط کاربری و تجربهٔ کاربری":"Interface and experience","پاپ‌آپ بدون اسکرول:":"Popup without scrolling:","همهٔ تب‌ها در ارتفاع ۶۰۰ پیکسل جا می‌شوند. دکمه‌ها حداقل ۳۲ پیکسل لمس دارند و کوچک‌ترین متن ۱۱٫۵ پیکسل است تا روی صفحه‌های کوچک هم خوانا باشد.":"Every tab fits in a 600-pixel-high popup. Buttons have a touch area of at least 32 pixels, and the smallest text is 11.5 pixels, so it stays readable on small screens.","بخش‌های جمع‌شونده:":"Collapsible sections:","«یادگیری و Storyboard» و «تنظیمات پیشرفته» جمع می‌شوند تا پاپ‌آپ شلوغ نشود.":"“Learn and Storyboard” and “Advanced settings” fold away so the popup stays uncluttered.","حالت روشن و تیره:":"Light and dark mode:","پاپ‌آپ، تنظیمات، صفحهٔ یادگیری و Storyboard هر دو حالت را دارند و رنگ‌ها در هر دو یکدست هستند.":"The popup, settings, the Learn page and Storyboard support both modes, with consistent colours in each.","توضیح بالای هر صفحه:":"A short note at the top of each page:","صفحهٔ یادگیری و Storyboard در بالا می‌گوید هر بخش چه کاری انجام می‌دهد و چطور شروع کنی.":"The Learn and Storyboard pages explain at the top what each part does and how to start.","ترجمه و هوش مصنوعی":"Translation and AI","چت، نقش‌آفرینی و نگارش بدون ورود باز هستند:":"Chat, roleplay and writing open without signing in:","این سه بخش دیگر پشت صفحهٔ ورود قرار نمی‌گیرند.":"These three areas no longer sit behind the sign-in screen.","کلید خودت، هر سرویس:":"Your own key, any service:","چت، نقش‌آفرینی و نگارش با کلید Gemini، OpenRouter، OpenAI یا سرویس اختصاصی خودت کار می‌کنند. دوبلهٔ زنده فقط با Gemini کار می‌کند.":"Chat, roleplay and writing work with your own Gemini, OpenRouter, OpenAI or custom service key. Live dubbing works only with Gemini.","ترجمهٔ کل صفحه:":"Full-page translation:","همهٔ متن قابل‌دیدن صفحه ترجمه می‌شود، نه فقط بخش اول. ترجمهٔ هر آدرس روی همان مرورگر ذخیره می‌شود تا دوباره لازم نباشد از نو ترجمه شود.":"All visible text on the page is translated, not just the first part. The translation of each address is kept in the same browser, so it does not need to be translated again.","ده استفادهٔ رایگان:":"Ten free uses:","ترجمه، دوبله و ترجمهٔ صفحه تا ده بار بدون ورود. هر ویدیو فقط یک بار حساب می‌شود، حتی اگر هم ترجمه و هم دوبله شود.":"Translation, dubbing and page translation, up to ten times without signing in. Each video counts once, even if you both translate and dub it.","وب‌اپلیکیشن":"Web app","شروع سریع:":"Quick start:","متن یا فایل زیرنویس را همان‌جا بگذار؛ ترجمه همان لحظه شروع می‌شود.":"Paste the subtitle text or drop the file right there, and translation starts at once.","کار بدون اینترنت:":"Works offline:","بعد از اولین باز شدن، برنامه بدون اتصال هم باز می‌شود و لغت‌ها و Storyboard روی دستگاهت می‌مانند. وقتی اینترنت قطع یا کند می‌شود، نوار بالای صفحه این را نشان می‌دهد.":"After the first visit, the app opens without a connection, and your words and Storyboard stay on your device. When the connection drops or slows down, a bar at the top says so.","ترجمهٔ صفحه‌نمایش:":"Screen translation:","یک تب یا برنامه را به اشتراک بگذار؛ متن آن ترجمه و روی تصویر نشان داده می‌شود.":"Share a tab or an app; its text is translated and shown over the picture.","کارت تصویری لغت:":"Word card image:","یک تصویر ۱۰۸۰ در ۱۳۵۰ با زمینهٔ تیره یا روشن بساز و بفرست.":"Make a 1080 × 1350 image of a word with a dark or light background and share it.","خروجی Word:":"Word export:","ترجمه‌ها، نقش‌آفرینی و نگارش را به فایل Word تبدیل کن.":"Turn translations, roleplay and writing into a Word file.","مدل پشتیبان Gemini:":"Gemini backup model:","اگر مدل اصلی بعد از ۷ ثانیه جواب ندهد، مدل پشتیبان کار را ادامه می‌دهد؛ لغت و دستور زبان دیگر منتظر پیام «تقاضای زیاد» نمی‌مانند.":"If the main model does not answer within 7 seconds, the backup model takes over, so words and grammar no longer wait for a “high demand” message.","بررسی حساب در اتصال کند:":"Account check on a slow connection:","اگر اتصال خیلی کند باشد، بررسی ورود بعد از ۴ ثانیه تمام می‌شود و کارت «در حال بررسی» بی‌پایان نمی‌ماند.":"If the connection is very slow, the sign-in check ends after 4 seconds, and the “checking” card does not stay on screen forever."},"ar":{"تغییرات مهم Subify lite":"أهم تحديثات Subify lite","نسخه جدید آماده است. اینجا مهم‌ترین قابلیت‌ها، پلتفرم‌های پشتیبانی‌شده و تغییرات ظاهری و فنی را یک‌جا می‌بینی.":"النسخة الجديدة جاهزة. هنا تجد أهم الميزات والمنصات المدعومة وتغييرات الواجهة والجوانب التقنية في مكان واحد.","پلتفرم‌های آموزشی":"المنصات التعليمية","این صفحه فقط برای نمایش تغییرات مهم نسخه است. بعد از مطالعه، روی «متوجه شدم» بزن تا دوباره در شروع مرورگر نمایش داده نشود.":"تعرض هذه الصفحة أهم تغييرات هذه النسخة. بعد القراءة اضغط «متوجه شدم» حتى لا تظهر مرة أخرى عند بدء تشغيل المتصفح.","متوجه شدم":"فهمت","این نسخه: ۲.۹.۴۱":"هذا الإصدار: 2.9.41","صفحهٔ یادگیری:":"صفحة التعلّم:","کنترل زبان دیگر روی متن بالای صفحه نمی‌افتد و عنوان و توضیح کامل دیده می‌شوند.":"لم يعد زر اللغة يغطي النص أعلى الصفحة، ويظهر العنوان والوصف كاملين.","پشتیبانی:":"الدعم:","دکمهٔ «پشتیبانی» در پنجرهٔ تازه‌ها به صفحهٔ تماس Subify می‌رود.":"زر «الدعم» في نافذة الجديد يفتح صفحة الاتصال بـ Subify.","نسخهٔ ۲.۹.۴۰":"الإصدار 2.9.40","سری روزانه در پاپ‌آپ:":"سلسلة الأيام في النافذة المنبثقة:","پاپ‌آپ نشان می‌دهد چند روز پشت‌هم کار کرده‌ای و امروز چند دقیقه از هدفت را رفته‌ای. با زدن روی هدف می‌توانی ۵، ۱۰ یا ۲۰ دقیقه انتخاب کنی. فقط روی همین دستگاه ذخیره می‌شود.":"تُظهر النافذة عدد الأيام المتتالية التي عملتَ فيها ودقائق اليوم مقارنةً بهدفك. اضغط على الهدف لاختيار 5 أو 10 أو 20 دقيقة. يُحفظ على هذا الجهاز فقط.","زبان رابط کاربری در ۷ زبان:":"واجهة المستخدم بسبع لغات:","پاپ‌آپ، تنظیمات، حساب، صفحهٔ یادگیری و صفحه‌های هوش مصنوعی به فارسی، انگلیسی، عربی، اسپانیایی، ترکی، فرانسوی و آلمانی ترجمه شده‌اند. جهت متن هم با زبان تغییر می‌کند.":"النافذة المنبثقة والإعدادات والحساب وصفحة التعلم وصفحات الذكاء الاصطناعي مترجمة إلى الفارسية والإنجليزية والعربية والإسبانية والتركية والفرنسية والألمانية. ويتغير اتجاه النص مع اللغة أيضاً.","تنظیمات ساده‌تر:":"إعدادات أبسط:","صفحهٔ تنظیمات حالا در پنج بخش است: خانه، ترجمه و دوبله، یادگیری، کلیدها و سرویس‌ها، حساب و پشتیبانی. هر چیز فقط یک جا آمده است.":"صفحة الإعدادات أصبحت الآن من خمسة أقسام: الرئيسية، والترجمة والدبلجة، والتعلم، والمفاتيح والخدمات، والحساب والدعم. يظهر كل عنصر في مكان واحد فقط.","تازه‌های این نسخه در تنظیمات:":"الجديد في هذه النسخة في الإعدادات:","بار اول که تنظیمات را باز کنی، همین توضیح‌ها را در یک پنجرهٔ کوتاه می‌بینی. برای هر نسخه فقط یک بار نشان داده می‌شود.":"عند أول فتح للإعدادات بعد التحديث، تظهر لك هذه الملاحظات في نافذة قصيرة. تظهر مرة واحدة لكل إصدار.","صفحه‌های هوش مصنوعی:":"صفحات الذكاء الاصطناعي:","هدر و چیدمان گفت‌وگو، خلاصه، نقش‌آفرینی، نگارش و تمرین تلفظ با بقیهٔ صفحه‌ها یکدست شده و در زبان‌های چپ‌به‌راست و راست‌به‌چپ درست چیده می‌شوند.":"أصبح رأس الصفحة وتخطيط المحادثة والملخص ولعب الأدوار والكتابة وتمرين النطق متوافقين مع بقية الصفحات، ويُرتّبان بشكل صحيح في اللغات من اليسار إلى اليمين ومن اليمين إلى اليسار.","اعداد و متن‌ها:":"الأرقام والنصوص:","در زبان‌های غیرفارسی عددها لاتین نشان داده می‌شوند و متن‌های نیمه‌فارسی دیگر در رابط کاربری دیده نمی‌شوند.":"في اللغات غير الفارسية تُعرض الأرقام بالأرقام اللاتينية، ولم تعد النصوص المختلطة بالفارسية تظهر في الواجهة.","حساب و ریست ماهانه:":"الحساب وإعادة الضبط الشهرية:","زمان بازنشانی ماهانهٔ سهمیه با قالب تاریخ و ساعت همان زبان نشان داده می‌شود، نه عدد خام.":"يُعرض وقت إعادة ضبط الحصة الشهرية بتنسيق التاريخ والوقت للغتك، لا كرقم خام.","نسخهٔ ۲.۹.۳۹":"الإصدار 2.9.39","ورود با نام کاربری و رمز:":"تسجيل الدخول باسم المستخدم وكلمة المرور:","حساب را با نام کاربری و رمز بساز یا وارد شو (ایمیل اختیاری است). ورود با Google، GitHub یا LinkedIn هم هست.":"أنشئ حسابًا باسم مستخدم وكلمة مرور (البريد الإلكتروني اختياري)، أو سجّل الدخول عبر Google أو GitHub أو LinkedIn.","یک کلمه را بزن تا مکث شود:":"اضغط على كلمة لإيقاف التشغيل مؤقتًا:","در حالت یادگیری، زدن روی یک کلمهٔ زیرنویس ویدیو را متوقف می‌کند تا معنی‌اش را بخوانی. با بستن معنی، پخش ادامه پیدا می‌کند.":"في وضع التعلّم، الضغط على كلمة في الترجمة يوقف الفيديو حتى تقرأ معناها. عند إغلاق المعنى يستأنف التشغيل.","کارت نقل‌قول با لینک:":"بطاقة اقتباس مع رابط:","کارت نقل‌قولی که از یادگیری ساخته می‌شود حالا لینک همان لحظهٔ ویدیوی یوتیوب را دارد. لینک هنگام ساخت کارت کپی می‌شود.":"بطاقة الاقتباس المُنشأة من قسم التعلم تتضمن الآن رابطًا إلى اللحظة نفسها في فيديو YouTube. يُنسخ الرابط عند إنشاء البطاقة.","نسخهٔ ۲.۹.۳۰: یادگیری و Storyboard":"الإصدار 2.9.30: التعلّم والـ Storyboard","بخش جدا با دو مسیر:":"قسم خاص بمدخلين:","زیر «یادگیری و Storyboard» توی پاپ‌آپ دو مورد هست: «یادگیری لغت» برای مرور لغت‌های ذخیره‌شده، و «Storyboard» برای دیدن صحنه‌های ترجمه‌شده. هر کدام یک توضیح کوتاه دارد و با یک کلیک باز می‌شود.":"ضمن «التعلّم والـ Storyboard» في النافذة مدخلان: «تعلّم الكلمات» لمراجعة الكلمات المحفوظة، و«Storyboard» لعرض المشاهد المترجمة. لكلٍّ منهما وصف قصير ويُفتح بنقرة واحدة.","همین دو ابزار از وب‌اپ هم:":"الأداتان نفسهما في تطبيق الويب:","کارت «یادگیری و Storyboard» توی خانه و زیر بخش حساب کاربری در تنظیمات هست، پس لازم نیست حتماً از پلیر یا پاپ‌آپ بروی.":"بطاقة «التعلّم والـ Storyboard» موجودة في الصفحة الرئيسية وتحت الحساب في الإعدادات، فلا حاجة للمرور عبر المشغّل أو النافذة المنبثقة.","خروجی Anki از یادگیری لغت:":"تصدير إلى Anki من التعلّم:","لغت‌های ذخیره‌شده با معنی و جمله، به فایل متنی جدا می‌روند که Anki بدون تبدیل وارد می‌کند.":"تُصدَّر الكلمات المحفوظة مع معناها وجملتها إلى ملف نصي منفصل يستورده Anki بلا أي تحويل.","Storyboard با ترتیب زمان:":"Storyboard بترتيب زمني:","هر صحنه با شمارهٔ ترتیب و زمان شروع نشان داده می‌شود، جملهٔ اصلی بالا و ترجمه زیر آن می‌آید و در حالت روشن و تیره یکسان دیده می‌شود.":"يظهر كل مشهد برقمه ووقت بدايته، مع الجملة الأصلية في الأعلى والترجمة تحتها، وتبدو متطابقة في الوضعين الفاتح والداكن.","Google Meet و زیرنویس زنده":"Google Meet والترجمة المباشرة","زیرنویس در Google Meet:":"الترجمة في Google Meet:","وقتی دوبلهٔ زنده را در Google Meet روشن می‌کنی، زیرنویس هم نشان داده می‌شود. این قابلیت فعلاً فقط در Chrome است، چون Firefox ضبط زندهٔ صدای جلسه را ندارد.":"عند تشغيل الدبلجة المباشرة في Google Meet تظهر الترجمة أيضًا. تعمل هذه الميزة حاليًا في Chrome فقط، لأن Firefox لا يستطيع التقاط الصوت المباشر للاجتماع.","توقف هم‌زمان صدا و زیرنویس:":"توقف الصوت والترجمة معًا:","وقتی دوبلهٔ زنده را متوقف می‌کنی، صدای دوبله و زیرنویس با هم می‌ایستند و با هم ادامه پیدا می‌کنند، تا از هم جدا نشوند.":"عند إيقاف الدبلجة المباشرة يتوقف الصوت المدبلج والترجمة معًا ويستأنفان معًا، حتى لا ينفصلا.","Google Meet در فهرست پلتفرم‌ها:":"Google Meet في قائمة المنصات:","Google Meet به پلتفرم‌های پشتیبانی‌شده اضافه شد.":"أُضيف Google Meet إلى المنصات المدعومة.","رابط کاربری و تجربهٔ کاربری":"الواجهة وتجربة الاستخدام","پاپ‌آپ بدون اسکرول:":"نافذة منبثقة بدون تمرير:","همهٔ تب‌ها در ارتفاع ۶۰۰ پیکسل جا می‌شوند. دکمه‌ها حداقل ۳۲ پیکسل لمس دارند و کوچک‌ترین متن ۱۱٫۵ پیکسل است تا روی صفحه‌های کوچک هم خوانا باشد.":"تتّسع كل التبويبات في نافذة بارتفاع 600 بكسل. الأزرار لا تقل منطقة اللمس فيها عن 32 بكسل، وأصغر نص 11.5 بكسل، ليبقى مقروءًا على الشاشات الصغيرة.","بخش‌های جمع‌شونده:":"أقسام قابلة للطي:","«یادگیری و Storyboard» و «تنظیمات پیشرفته» جمع می‌شوند تا پاپ‌آپ شلوغ نشود.":"تُطوى الأقسام «التعلّم والـ Storyboard» و«الإعدادات المتقدمة» كي تبقى النافذة غير مزدحمة.","حالت روشن و تیره:":"الوضع الفاتح والداكن:","پاپ‌آپ، تنظیمات، صفحهٔ یادگیری و Storyboard هر دو حالت را دارند و رنگ‌ها در هر دو یکدست هستند.":"تدعم النافذة والإعدادات وصفحة التعلّم والـ Storyboard الوضعين، بألوان متناسقة في كليهما.","توضیح بالای هر صفحه:":"ملاحظة قصيرة في أعلى كل صفحة:","صفحهٔ یادگیری و Storyboard در بالا می‌گوید هر بخش چه کاری انجام می‌دهد و چطور شروع کنی.":"تشرح صفحتا التعلّم والـ Storyboard في الأعلى ما يفعله كل قسم وكيف تبدأ.","ترجمه و هوش مصنوعی":"الترجمة والذكاء الاصطناعي","چت، نقش‌آفرینی و نگارش بدون ورود باز هستند:":"المحادثة ولعب الأدوار والكتابة متاحة دون تسجيل الدخول:","این سه بخش دیگر پشت صفحهٔ ورود قرار نمی‌گیرند.":"لم تعد هذه الأقسام الثلاثة خلف شاشة تسجيل الدخول.","کلید خودت، هر سرویس:":"مفتاحك الخاص، أي خدمة:","چت، نقش‌آفرینی و نگارش با کلید Gemini، OpenRouter، OpenAI یا سرویس اختصاصی خودت کار می‌کنند. دوبلهٔ زنده فقط با Gemini کار می‌کند.":"تعمل المحادثة ولعب الأدوار والكتابة بمفتاحك الخاص من Gemini أو OpenRouter أو OpenAI أو خدمة مخصصة. الدبلجة المباشرة تعمل مع Gemini فقط.","ترجمهٔ کل صفحه:":"ترجمة الصفحة كاملة:","همهٔ متن قابل‌دیدن صفحه ترجمه می‌شود، نه فقط بخش اول. ترجمهٔ هر آدرس روی همان مرورگر ذخیره می‌شود تا دوباره لازم نباشد از نو ترجمه شود.":"تُترجم كل النصوص الظاهرة في الصفحة، لا الجزء الأول فقط. تُحفظ ترجمة كل عنوان في المتصفح نفسه فلا تحتاج إلى ترجمة مرة أخرى.","ده استفادهٔ رایگان:":"عشر استخدامات مجانية:","ترجمه، دوبله و ترجمهٔ صفحه تا ده بار بدون ورود. هر ویدیو فقط یک بار حساب می‌شود، حتی اگر هم ترجمه و هم دوبله شود.":"الترجمة والدبلجة وترجمة الصفحة حتى عشر مرات دون تسجيل الدخول. يُحتسب كل فيديو مرة واحدة حتى لو ترجمته ودبلجته معًا.","وب‌اپلیکیشن":"تطبيق الويب","شروع سریع:":"بداية سريعة:","متن یا فایل زیرنویس را همان‌جا بگذار؛ ترجمه همان لحظه شروع می‌شود.":"ألصق نص الترجمة أو أفلِت الملف هناك، وتبدأ الترجمة فورًا.","کار بدون اینترنت:":"يعمل دون اتصال:","بعد از اولین باز شدن، برنامه بدون اتصال هم باز می‌شود و لغت‌ها و Storyboard روی دستگاهت می‌مانند. وقتی اینترنت قطع یا کند می‌شود، نوار بالای صفحه این را نشان می‌دهد.":"بعد أول زيارة يُفتح التطبيق دون اتصال، وتبقى كلماتك وStoryboard على جهازك. عند انقطاع الإنترنت أو بطئه يُظهر شريط في الأعلى ذلك.","ترجمهٔ صفحه‌نمایش:":"ترجمة الشاشة:","یک تب یا برنامه را به اشتراک بگذار؛ متن آن ترجمه و روی تصویر نشان داده می‌شود.":"شارك تبويبًا أو تطبيقًا؛ تُترجم نصوصه وتظهر فوق الصورة.","کارت تصویری لغت:":"صورة بطاقة الكلمة:","یک تصویر ۱۰۸۰ در ۱۳۵۰ با زمینهٔ تیره یا روشن بساز و بفرست.":"أنشئ صورة بقياس 1080 × 1350 لكلمة بخلفية داكنة أو فاتحة وشاركها.","خروجی Word:":"تصدير إلى Word:","ترجمه‌ها، نقش‌آفرینی و نگارش را به فایل Word تبدیل کن.":"حوّل الترجمات ولعب الأدوار والكتابة إلى ملف Word.","مدل پشتیبان Gemini:":"نموذج Gemini الاحتياطي:","اگر مدل اصلی بعد از ۷ ثانیه جواب ندهد، مدل پشتیبان کار را ادامه می‌دهد؛ لغت و دستور زبان دیگر منتظر پیام «تقاضای زیاد» نمی‌مانند.":"إذا لم يرد النموذج الرئيسي خلال 7 ثوانٍ، يتولى النموذج الاحتياطي العمل، فلم تعد الكلمات والقواعد تنتظر رسالة «الطلب المرتفع».","بررسی حساب در اتصال کند:":"التحقق من الحساب على اتصال بطيء:","اگر اتصال خیلی کند باشد، بررسی ورود بعد از ۴ ثانیه تمام می‌شود و کارت «در حال بررسی» بی‌پایان نمی‌ماند.":"إذا كان الاتصال بطيئًا جدًا ينتهي التحقق من تسجيل الدخول بعد 4 ثوانٍ، ولا تبقى بطاقة «جارٍ التحقق» إلى ما لا نهاية."},"es":{"تغییرات مهم Subify lite":"Novedades importantes de Subify lite","نسخه جدید آماده است. اینجا مهم‌ترین قابلیت‌ها، پلتفرم‌های پشتیبانی‌شده و تغییرات ظاهری و فنی را یک‌جا می‌بینی.":"La nueva versión ya está lista. Aquí verás en un solo lugar las funciones principales, las plataformas compatibles y los cambios de interfaz y técnicos.","پلتفرم‌های آموزشی":"Plataformas educativas","این صفحه فقط برای نمایش تغییرات مهم نسخه است. بعد از مطالعه، روی «متوجه شدم» بزن تا دوباره در شروع مرورگر نمایش داده نشود.":"Esta página muestra los cambios principales de esta versión. Cuando termines de leer, pulsa «Entendido» para que no vuelva a aparecer al iniciar el navegador.","متوجه شدم":"Entendido","این نسخه: ۲.۹.۴۱":"Esta versión: 2.9.41","صفحهٔ یادگیری:":"Página de aprendizaje:","کنترل زبان دیگر روی متن بالای صفحه نمی‌افتد و عنوان و توضیح کامل دیده می‌شوند.":"El selector de idioma ya no tapa el texto de la parte superior, así que el título y la descripción se ven completos.","پشتیبانی:":"Soporte:","دکمهٔ «پشتیبانی» در پنجرهٔ تازه‌ها به صفحهٔ تماس Subify می‌رود.":"El botón «Soporte» de la ventana de novedades abre ahora la página de contacto de Subify.","نسخهٔ ۲.۹.۴۰":"Versión 2.9.40","سری روزانه در پاپ‌آپ:":"Racha diaria en el popup:","پاپ‌آپ نشان می‌دهد چند روز پشت‌هم کار کرده‌ای و امروز چند دقیقه از هدفت را رفته‌ای. با زدن روی هدف می‌توانی ۵، ۱۰ یا ۲۰ دقیقه انتخاب کنی. فقط روی همین دستگاه ذخیره می‌شود.":"El popup muestra cuántos días seguidos has trabajado y los minutos de hoy frente a tu objetivo. Toca el objetivo para elegir 5, 10 o 20 minutos. Se guarda solo en este dispositivo.","زبان رابط کاربری در ۷ زبان:":"Interfaz en 7 idiomas:","پاپ‌آپ، تنظیمات، حساب، صفحهٔ یادگیری و صفحه‌های هوش مصنوعی به فارسی، انگلیسی، عربی، اسپانیایی، ترکی، فرانسوی و آلمانی ترجمه شده‌اند. جهت متن هم با زبان تغییر می‌کند.":"El popup, los ajustes, la cuenta, la página de aprendizaje y las páginas de IA están traducidos al persa, inglés, árabe, español, turco, francés y alemán. La dirección del texto también cambia con el idioma.","تنظیمات ساده‌تر:":"Ajustes más sencillos:","صفحهٔ تنظیمات حالا در پنج بخش است: خانه، ترجمه و دوبله، یادگیری، کلیدها و سرویس‌ها، حساب و پشتیبانی. هر چیز فقط یک جا آمده است.":"La página de ajustes ahora tiene cinco secciones: Inicio, Traducción y doblaje, Aprendizaje, Claves y servicios, y Cuenta y soporte. Cada elemento aparece en un solo lugar.","تازه‌های این نسخه در تنظیمات:":"Novedades de esta versión en ajustes:","بار اول که تنظیمات را باز کنی، همین توضیح‌ها را در یک پنجرهٔ کوتاه می‌بینی. برای هر نسخه فقط یک بار نشان داده می‌شود.":"La primera vez que abras los ajustes tras una actualización, verás estas notas en una ventana breve. Aparece una vez por versión.","صفحه‌های هوش مصنوعی:":"Páginas de IA:","هدر و چیدمان گفت‌وگو، خلاصه، نقش‌آفرینی، نگارش و تمرین تلفظ با بقیهٔ صفحه‌ها یکدست شده و در زبان‌های چپ‌به‌راست و راست‌به‌چپ درست چیده می‌شوند.":"El encabezado y la distribución de Chat, Resumen, Rol, Escritura y Pronunciación ahora coinciden con las demás páginas y se alinean bien tanto en idiomas de izquierda a derecha como de derecha a izquierda.","اعداد و متن‌ها:":"Números y textos:","در زبان‌های غیرفارسی عددها لاتین نشان داده می‌شوند و متن‌های نیمه‌فارسی دیگر در رابط کاربری دیده نمی‌شوند.":"En los idiomas que no son persas, los números se muestran con cifras latinas y ya no aparece texto mezclado en persa en la interfaz.","حساب و ریست ماهانه:":"Cuenta y reinicio mensual:","زمان بازنشانی ماهانهٔ سهمیه با قالب تاریخ و ساعت همان زبان نشان داده می‌شود، نه عدد خام.":"La hora de reinicio mensual de la cuota se muestra con el formato de fecha y hora de tu idioma, no como un número sin formato.","نسخهٔ ۲.۹.۳۹":"Versión 2.9.39","ورود با نام کاربری و رمز:":"Inicio de sesión con usuario y contraseña:","حساب را با نام کاربری و رمز بساز یا وارد شو (ایمیل اختیاری است). ورود با Google، GitHub یا LinkedIn هم هست.":"Crea una cuenta con usuario y contraseña (el correo es opcional) o inicia sesión con Google, GitHub o LinkedIn.","یک کلمه را بزن تا مکث شود:":"Toca una palabra para pausar:","در حالت یادگیری، زدن روی یک کلمهٔ زیرنویس ویدیو را متوقف می‌کند تا معنی‌اش را بخوانی. با بستن معنی، پخش ادامه پیدا می‌کند.":"En un modo de aprendizaje, al tocar una palabra del subtítulo el video se pausa para que leas su significado. Al cerrarlo, la reproducción continúa.","کارت نقل‌قول با لینک:":"Tarjeta de cita con enlace:","کارت نقل‌قولی که از یادگیری ساخته می‌شود حالا لینک همان لحظهٔ ویدیوی یوتیوب را دارد. لینک هنگام ساخت کارت کپی می‌شود.":"La tarjeta de cita creada desde Aprendizaje incluye ahora un enlace al mismo momento del video de YouTube. El enlace se copia al crear la tarjeta.","نسخهٔ ۲.۹.۳۰: یادگیری و Storyboard":"Versión 2.9.30: Aprendizaje y Storyboard","بخش جدا با دو مسیر:":"Una sección propia con dos entradas:","زیر «یادگیری و Storyboard» توی پاپ‌آپ دو مورد هست: «یادگیری لغت» برای مرور لغت‌های ذخیره‌شده، و «Storyboard» برای دیدن صحنه‌های ترجمه‌شده. هر کدام یک توضیح کوتاه دارد و با یک کلیک باز می‌شود.":"En «Aprendizaje y Storyboard» del popup hay dos opciones: «Palabras» para repasar las palabras guardadas, y «Storyboard» para ver las escenas traducidas. Cada una tiene una breve descripción y se abre con un clic.","همین دو ابزار از وب‌اپ هم:":"Las mismas dos herramientas en la web app:","کارت «یادگیری و Storyboard» توی خانه و زیر بخش حساب کاربری در تنظیمات هست، پس لازم نیست حتماً از پلیر یا پاپ‌آپ بروی.":"La tarjeta «Aprendizaje y Storyboard» está en Inicio y en tu cuenta dentro de Ajustes, así que no necesitas pasar por el reproductor ni por el popup.","خروجی Anki از یادگیری لغت:":"Exportación a Anki desde Aprendizaje:","لغت‌های ذخیره‌شده با معنی و جمله، به فایل متنی جدا می‌روند که Anki بدون تبدیل وارد می‌کند.":"Las palabras guardadas, con su significado y frase, se exportan a un archivo de texto que Anki importa sin conversión.","Storyboard با ترتیب زمان:":"Storyboard en orden cronológico:","هر صحنه با شمارهٔ ترتیب و زمان شروع نشان داده می‌شود، جملهٔ اصلی بالا و ترجمه زیر آن می‌آید و در حالت روشن و تیره یکسان دیده می‌شود.":"Cada escena muestra su número y su hora de inicio, la frase original arriba y la traducción debajo, y se ve igual en modo claro y oscuro.","Google Meet و زیرنویس زنده":"Google Meet y subtítulos en vivo","زیرنویس در Google Meet:":"Subtítulos en Google Meet:","وقتی دوبلهٔ زنده را در Google Meet روشن می‌کنی، زیرنویس هم نشان داده می‌شود. این قابلیت فعلاً فقط در Chrome است، چون Firefox ضبط زندهٔ صدای جلسه را ندارد.":"Al activar el doblaje en vivo en Google Meet, también aparecen los subtítulos. Por ahora solo funciona en Chrome, porque Firefox no puede capturar el audio en vivo de una reunión.","توقف هم‌زمان صدا و زیرنویس:":"El audio y los subtítulos se detienen juntos:","وقتی دوبلهٔ زنده را متوقف می‌کنی، صدای دوبله و زیرنویس با هم می‌ایستند و با هم ادامه پیدا می‌کنند، تا از هم جدا نشوند.":"Al detener el doblaje en vivo, el audio doblado y los subtítulos se detienen y se reanudan juntos, para que no se desincronicen.","Google Meet در فهرست پلتفرم‌ها:":"Google Meet en la lista de plataformas:","Google Meet به پلتفرم‌های پشتیبانی‌شده اضافه شد.":"Google Meet se ha añadido a las plataformas compatibles.","رابط کاربری و تجربهٔ کاربری":"Interfaz y experiencia","پاپ‌آپ بدون اسکرول:":"Popup sin desplazamiento:","همهٔ تب‌ها در ارتفاع ۶۰۰ پیکسل جا می‌شوند. دکمه‌ها حداقل ۳۲ پیکسل لمس دارند و کوچک‌ترین متن ۱۱٫۵ پیکسل است تا روی صفحه‌های کوچک هم خوانا باشد.":"Todas las pestañas caben en un popup de 600 píxeles de alto. Los botones tienen un área táctil de al menos 32 píxeles y el texto más pequeño mide 11,5 píxeles, para que se lea bien en pantallas pequeñas.","بخش‌های جمع‌شونده:":"Secciones plegables:","«یادگیری و Storyboard» و «تنظیمات پیشرفته» جمع می‌شوند تا پاپ‌آپ شلوغ نشود.":"«Aprendizaje y Storyboard» y «Ajustes avanzados» se pliegan para que el popup no se llene.","حالت روشن و تیره:":"Modo claro y oscuro:","پاپ‌آپ، تنظیمات، صفحهٔ یادگیری و Storyboard هر دو حالت را دارند و رنگ‌ها در هر دو یکدست هستند.":"El popup, los ajustes, la página de Aprendizaje y Storyboard admiten ambos modos, con colores coherentes en cada uno.","توضیح بالای هر صفحه:":"Una nota breve al inicio de cada página:","صفحهٔ یادگیری و Storyboard در بالا می‌گوید هر بخش چه کاری انجام می‌دهد و چطور شروع کنی.":"Las páginas de Aprendizaje y Storyboard explican arriba qué hace cada parte y cómo empezar.","ترجمه و هوش مصنوعی":"Traducción e IA","چت، نقش‌آفرینی و نگارش بدون ورود باز هستند:":"Chat, rol y escritura se abren sin iniciar sesión:","این سه بخش دیگر پشت صفحهٔ ورود قرار نمی‌گیرند.":"Estas tres secciones ya no están detrás de la pantalla de inicio de sesión.","کلید خودت، هر سرویس:":"Tu propia clave, cualquier servicio:","چت، نقش‌آفرینی و نگارش با کلید Gemini، OpenRouter، OpenAI یا سرویس اختصاصی خودت کار می‌کنند. دوبلهٔ زنده فقط با Gemini کار می‌کند.":"El chat, el rol y la escritura funcionan con tu propia clave de Gemini, OpenRouter, OpenAI o un servicio personalizado. El doblaje en vivo solo funciona con Gemini.","ترجمهٔ کل صفحه:":"Traducción de página completa:","همهٔ متن قابل‌دیدن صفحه ترجمه می‌شود، نه فقط بخش اول. ترجمهٔ هر آدرس روی همان مرورگر ذخیره می‌شود تا دوباره لازم نباشد از نو ترجمه شود.":"Se traduce todo el texto visible de la página, no solo la primera parte. La traducción de cada dirección se guarda en el mismo navegador, así que no hace falta volver a traducirla.","ده استفادهٔ رایگان:":"Diez usos gratis:","ترجمه، دوبله و ترجمهٔ صفحه تا ده بار بدون ورود. هر ویدیو فقط یک بار حساب می‌شود، حتی اگر هم ترجمه و هم دوبله شود.":"Traducción, doblaje y traducción de página, hasta diez veces sin iniciar sesión. Cada video cuenta una sola vez, aunque lo traduzcas y lo dobles.","وب‌اپلیکیشن":"Aplicación web","شروع سریع:":"Inicio rápido:","متن یا فایل زیرنویس را همان‌جا بگذار؛ ترجمه همان لحظه شروع می‌شود.":"Pega el texto de los subtítulos o suelta el archivo ahí mismo, y la traducción empieza al instante.","کار بدون اینترنت:":"Funciona sin conexión:","بعد از اولین باز شدن، برنامه بدون اتصال هم باز می‌شود و لغت‌ها و Storyboard روی دستگاهت می‌مانند. وقتی اینترنت قطع یا کند می‌شود، نوار بالای صفحه این را نشان می‌دهد.":"Después de la primera visita, la app se abre sin conexión y tus palabras y Storyboard se quedan en tu dispositivo. Cuando la conexión se corta o se vuelve lenta, una barra arriba lo indica.","ترجمهٔ صفحه‌نمایش:":"Traducción de pantalla:","یک تب یا برنامه را به اشتراک بگذار؛ متن آن ترجمه و روی تصویر نشان داده می‌شود.":"Comparte una pestaña o una app; su texto se traduce y se muestra sobre la imagen.","کارت تصویری لغت:":"Imagen de tarjeta de palabra:","یک تصویر ۱۰۸۰ در ۱۳۵۰ با زمینهٔ تیره یا روشن بساز و بفرست.":"Crea una imagen de 1080 × 1350 de una palabra con fondo oscuro o claro y compártela.","خروجی Word:":"Exportar a Word:","ترجمه‌ها، نقش‌آفرینی و نگارش را به فایل Word تبدیل کن.":"Convierte las traducciones, el rol y la escritura en un archivo de Word.","مدل پشتیبان Gemini:":"Modelo de respaldo de Gemini:","اگر مدل اصلی بعد از ۷ ثانیه جواب ندهد، مدل پشتیبان کار را ادامه می‌دهد؛ لغت و دستور زبان دیگر منتظر پیام «تقاضای زیاد» نمی‌مانند.":"Si el modelo principal no responde en 7 segundos, el modelo de respaldo continúa, así que las palabras y la gramática ya no esperan el mensaje de «demanda alta».","بررسی حساب در اتصال کند:":"Verificación de cuenta con conexión lenta:","اگر اتصال خیلی کند باشد، بررسی ورود بعد از ۴ ثانیه تمام می‌شود و کارت «در حال بررسی» بی‌پایان نمی‌ماند.":"Si la conexión es muy lenta, la comprobación de inicio de sesión termina a los 4 segundos y la tarjeta «comprobando» no se queda para siempre."},"tr":{"تغییرات مهم Subify lite":"Subify lite'daki önemli güncellemeler","نسخه جدید آماده است. اینجا مهم‌ترین قابلیت‌ها، پلتفرم‌های پشتیبانی‌شده و تغییرات ظاهری و فنی را یک‌جا می‌بینی.":"Yeni sürüm hazır. Burada ana özellikleri, desteklenen platformları ve arayüz ile teknik değişiklikleri tek yerde görebilirsin.","پلتفرم‌های آموزشی":"Eğitim platformları","این صفحه فقط برای نمایش تغییرات مهم نسخه است. بعد از مطالعه، روی «متوجه شدم» بزن تا دوباره در شروع مرورگر نمایش داده نشود.":"Bu sayfa bu sürümdeki başlıca değişiklikleri gösterir. Okuduktan sonra «Anladım» düğmesine bas; böylece tarayıcı açıldığında tekrar görünmez.","متوجه شدم":"Anladım","این نسخه: ۲.۹.۴۱":"Bu sürüm: 2.9.41","صفحهٔ یادگیری:":"Öğrenme sayfası:","کنترل زبان دیگر روی متن بالای صفحه نمی‌افتد و عنوان و توضیح کامل دیده می‌شوند.":"Dil kontrolü artık sayfanın üstündeki metnin üzerine binmiyor; başlık ve açıklama tamamen görünüyor.","پشتیبانی:":"Destek:","دکمهٔ «پشتیبانی» در پنجرهٔ تازه‌ها به صفحهٔ تماس Subify می‌رود.":"Yenilikler penceresindeki «Destek» düğmesi artık Subify iletişim sayfasını açar.","نسخهٔ ۲.۹.۴۰":"Sürüm 2.9.40","سری روزانه در پاپ‌آپ:":"Açılır pencerede günlük seri:","پاپ‌آپ نشان می‌دهد چند روز پشت‌هم کار کرده‌ای و امروز چند دقیقه از هدفت را رفته‌ای. با زدن روی هدف می‌توانی ۵، ۱۰ یا ۲۰ دقیقه انتخاب کنی. فقط روی همین دستگاه ذخیره می‌شود.":"Açılır pencere, üst üste kaç gün çalıştığını ve bugünkü dakikalarını hedefinle birlikte gösterir. Hedefe dokunarak 5, 10 veya 20 dakika seçebilirsin. Yalnızca bu cihazda saklanır.","زبان رابط کاربری در ۷ زبان:":"7 dilde arayüz:","پاپ‌آپ، تنظیمات، حساب، صفحهٔ یادگیری و صفحه‌های هوش مصنوعی به فارسی، انگلیسی، عربی، اسپانیایی، ترکی، فرانسوی و آلمانی ترجمه شده‌اند. جهت متن هم با زبان تغییر می‌کند.":"Açılır pencere, ayarlar, hesap, öğrenme sayfası ve yapay zekâ sayfaları Farsça, İngilizce, Arapça, İspanyolca, Türkçe, Fransızca ve Almanca’ya çevrildi. Metin yönü de dile göre değişir.","تنظیمات ساده‌تر:":"Daha basit ayarlar:","صفحهٔ تنظیمات حالا در پنج بخش است: خانه، ترجمه و دوبله، یادگیری، کلیدها و سرویس‌ها، حساب و پشتیبانی. هر چیز فقط یک جا آمده است.":"Ayarlar sayfası artık beş bölümden oluşuyor: Ana sayfa, Çeviri ve dublaj, Öğrenme, Anahtarlar ve hizmetler, Hesap ve destek. Her şey yalnızca bir yerde yer alıyor.","تازه‌های این نسخه در تنظیمات:":"Bu sürümdeki yenilikler ayarlarda:","بار اول که تنظیمات را باز کنی، همین توضیح‌ها را در یک پنجرهٔ کوتاه می‌بینی. برای هر نسخه فقط یک بار نشان داده می‌شود.":"Güncellemeden sonra ayarları ilk açtığında bu notları kısa bir pencerede görürsün. Her sürüm için yalnızca bir kez gösterilir.","صفحه‌های هوش مصنوعی:":"Yapay zekâ sayfaları:","هدر و چیدمان گفت‌وگو، خلاصه، نقش‌آفرینی، نگارش و تمرین تلفظ با بقیهٔ صفحه‌ها یکدست شده و در زبان‌های چپ‌به‌راست و راست‌به‌چپ درست چیده می‌شوند.":"Sohbet, Özet, Rol yapma, Yazma ve Telaffuz sayfalarının başlığı ve düzeni diğer sayfalarla uyumlu hale geldi; soldan sağa ve sağdan sola dillerde doğru hizalanıyor.","اعداد و متن‌ها:":"Sayılar ve metinler:","در زبان‌های غیرفارسی عددها لاتین نشان داده می‌شوند و متن‌های نیمه‌فارسی دیگر در رابط کاربری دیده نمی‌شوند.":"Farsça dışındaki dillerde sayılar Latin rakamlarıyla gösterilir ve arayüzde artık karışık Farsça metin görünmez.","حساب و ریست ماهانه:":"Hesap ve aylık sıfırlama:","زمان بازنشانی ماهانهٔ سهمیه با قالب تاریخ و ساعت همان زبان نشان داده می‌شود، نه عدد خام.":"Aylık kotanın sıfırlanma zamanı ham bir sayı yerine dilinin tarih ve saat biçiminde gösterilir.","نسخهٔ ۲.۹.۳۹":"Sürüm 2.9.39","ورود با نام کاربری و رمز:":"Kullanıcı adı ve şifreyle giriş:","حساب را با نام کاربری و رمز بساز یا وارد شو (ایمیل اختیاری است). ورود با Google، GitHub یا LinkedIn هم هست.":"Kullanıcı adı ve şifreyle bir hesap oluştur (e-posta isteğe bağlı) ya da Google, GitHub veya LinkedIn ile giriş yap.","یک کلمه را بزن تا مکث شود:":"Duraklatmak için bir kelimeye dokun:","در حالت یادگیری، زدن روی یک کلمهٔ زیرنویس ویدیو را متوقف می‌کند تا معنی‌اش را بخوانی. با بستن معنی، پخش ادامه پیدا می‌کند.":"Bir öğrenme modunda altyazıdaki bir kelimeye dokunmak, anlamını okuyabilmen için videoyu duraklatır. Anlamı kapatınca oynatma devam eder.","کارت نقل‌قول با لینک:":"Bağlantılı alıntı kartı:","کارت نقل‌قولی که از یادگیری ساخته می‌شود حالا لینک همان لحظهٔ ویدیوی یوتیوب را دارد. لینک هنگام ساخت کارت کپی می‌شود.":"Öğrenme bölümünden oluşturulan alıntı kartı artık YouTube videosunun aynı anına giden bağlantıyı içeriyor. Kart oluşturulduğunda bağlantı kopyalanır.","نسخهٔ ۲.۹.۳۰: یادگیری و Storyboard":"Sürüm 2.9.30: Öğrenme ve Storyboard","بخش جدا با دو مسیر:":"İki girişi olan ayrı bir bölüm:","زیر «یادگیری و Storyboard» توی پاپ‌آپ دو مورد هست: «یادگیری لغت» برای مرور لغت‌های ذخیره‌شده، و «Storyboard» برای دیدن صحنه‌های ترجمه‌شده. هر کدام یک توضیح کوتاه دارد و با یک کلیک باز می‌شود.":"Açılır pencerede «Öğrenme ve Storyboard» altında iki seçenek var: kaydettiğin kelimeleri gözden geçirmek için «Kelime öğrenme», çevrilmiş sahneleri görmek için «Storyboard». Her birinin kısa bir açıklaması var ve tek tıklamayla açılır.","همین دو ابزار از وب‌اپ هم:":"Web uygulamasında aynı iki araç:","کارت «یادگیری و Storyboard» توی خانه و زیر بخش حساب کاربری در تنظیمات هست، پس لازم نیست حتماً از پلیر یا پاپ‌آپ بروی.":"«Öğrenme ve Storyboard» kartı Ana sayfada ve Ayarlar’da hesabının altında; bu yüzden oynatıcıya veya açılır pencereye gitmek zorunda değilsin.","خروجی Anki از یادگیری لغت:":"Öğrenme bölümünden Anki dışa aktarımı:","لغت‌های ذخیره‌شده با معنی و جمله، به فایل متنی جدا می‌روند که Anki بدون تبدیل وارد می‌کند.":"Kaydedilen kelimeler anlamı ve cümlesiyle birlikte, Anki’nin dönüştürme gerektirmeden içe aktardığı ayrı bir metin dosyasına aktarılır.","Storyboard با ترتیب زمان:":"Storyboard zaman sırasıyla:","هر صحنه با شمارهٔ ترتیب و زمان شروع نشان داده می‌شود، جملهٔ اصلی بالا و ترجمه زیر آن می‌آید و در حالت روشن و تیره یکسان دیده می‌شود.":"Her sahne sıra numarası ve başlangıç zamanıyla gösterilir; üstte orijinal cümle, altında çeviri yer alır ve açık ile koyu modda aynı görünür.","Google Meet و زیرنویس زنده":"Google Meet ve canlı altyazı","زیرنویس در Google Meet:":"Google Meet'te altyazı:","وقتی دوبلهٔ زنده را در Google Meet روشن می‌کنی، زیرنویس هم نشان داده می‌شود. این قابلیت فعلاً فقط در Chrome است، چون Firefox ضبط زندهٔ صدای جلسه را ندارد.":"Google Meet'te canlı dublajı açtığında altyazılar da görünür. Şimdilik yalnızca Chrome'da çalışır; Firefox bir toplantının canlı sesini yakalayamaz.","توقف هم‌زمان صدا و زیرنویس:":"Ses ve altyazı birlikte durur:","وقتی دوبلهٔ زنده را متوقف می‌کنی، صدای دوبله و زیرنویس با هم می‌ایستند و با هم ادامه پیدا می‌کنند، تا از هم جدا نشوند.":"Canlı dublajı durdurduğunda dublaj sesi ve altyazılar birlikte durur ve birlikte devam eder; böylece birbirinden kopmazlar.","Google Meet در فهرست پلتفرم‌ها:":"Platform listesinde Google Meet:","Google Meet به پلتفرم‌های پشتیبانی‌شده اضافه شد.":"Google Meet, desteklenen platformlara eklendi.","رابط کاربری و تجربهٔ کاربری":"Arayüz ve kullanım deneyimi","پاپ‌آپ بدون اسکرول:":"Kaydırmasız açılır pencere:","همهٔ تب‌ها در ارتفاع ۶۰۰ پیکسل جا می‌شوند. دکمه‌ها حداقل ۳۲ پیکسل لمس دارند و کوچک‌ترین متن ۱۱٫۵ پیکسل است تا روی صفحه‌های کوچک هم خوانا باشد.":"Tüm sekmeler 600 piksel yüksekliğindeki açılır pencereye sığar. Düğmelerin dokunma alanı en az 32 piksel, en küçük metin 11,5 pikseldir; küçük ekranlarda da okunabilir kalır.","بخش‌های جمع‌شونده:":"Daraltılabilir bölümler:","«یادگیری و Storyboard» و «تنظیمات پیشرفته» جمع می‌شوند تا پاپ‌آپ شلوغ نشود.":"«Öğrenme ve Storyboard» ve «Gelişmiş ayarlar» katlanır; böylece açılır pencere kalabalık görünmez.","حالت روشن و تیره:":"Açık ve koyu mod:","پاپ‌آپ، تنظیمات، صفحهٔ یادگیری و Storyboard هر دو حالت را دارند و رنگ‌ها در هر دو یکدست هستند.":"Açılır pencere, ayarlar, Öğrenme sayfası ve Storyboard iki modu da destekler; renkler her iki modda tutarlıdır.","توضیح بالای هر صفحه:":"Her sayfanın üstünde kısa bir not:","صفحهٔ یادگیری و Storyboard در بالا می‌گوید هر بخش چه کاری انجام می‌دهد و چطور شروع کنی.":"Öğrenme ve Storyboard sayfaları, her bölümün ne işe yaradığını ve nasıl başlanacağını üstte anlatır.","ترجمه و هوش مصنوعی":"Çeviri ve yapay zekâ","چت، نقش‌آفرینی و نگارش بدون ورود باز هستند:":"Sohbet, rol yapma ve yazma giriş yapmadan açılır:","این سه بخش دیگر پشت صفحهٔ ورود قرار نمی‌گیرند.":"Bu üç bölüm artık giriş ekranının arkasında kalmıyor.","کلید خودت، هر سرویس:":"Kendi anahtarın, her hizmet:","چت، نقش‌آفرینی و نگارش با کلید Gemini، OpenRouter، OpenAI یا سرویس اختصاصی خودت کار می‌کنند. دوبلهٔ زنده فقط با Gemini کار می‌کند.":"Sohbet, rol yapma ve yazma kendi Gemini, OpenRouter, OpenAI veya özel hizmet anahtarınla çalışır. Canlı dublaj yalnızca Gemini ile çalışır.","ترجمهٔ کل صفحه:":"Tam sayfa çevirisi:","همهٔ متن قابل‌دیدن صفحه ترجمه می‌شود، نه فقط بخش اول. ترجمهٔ هر آدرس روی همان مرورگر ذخیره می‌شود تا دوباره لازم نباشد از نو ترجمه شود.":"Sayfada görünen tüm metin çevrilir, yalnızca ilk kısım değil. Her adresin çevirisi aynı tarayıcıda saklanır; bu yüzden yeniden çevirmek gerekmez.","ده استفادهٔ رایگان:":"On ücretsiz kullanım:","ترجمه، دوبله و ترجمهٔ صفحه تا ده بار بدون ورود. هر ویدیو فقط یک بار حساب می‌شود، حتی اگر هم ترجمه و هم دوبله شود.":"Çeviri, dublaj ve sayfa çevirisi, giriş yapmadan en fazla on kez. Bir video, hem çevrilse hem dublajlansa da yalnızca bir kez sayılır.","وب‌اپلیکیشن":"Web uygulaması","شروع سریع:":"Hızlı başlangıç:","متن یا فایل زیرنویس را همان‌جا بگذار؛ ترجمه همان لحظه شروع می‌شود.":"Altyazı metnini yapıştır ya da dosyayı oraya bırak; çeviri hemen başlar.","کار بدون اینترنت:":"Çevrimdışı çalışır:","بعد از اولین باز شدن، برنامه بدون اتصال هم باز می‌شود و لغت‌ها و Storyboard روی دستگاهت می‌مانند. وقتی اینترنت قطع یا کند می‌شود، نوار بالای صفحه این را نشان می‌دهد.":"İlk ziyaretten sonra uygulama bağlantı olmadan açılır; kelimelerin ve Storyboard’ın cihazında kalır. Bağlantı kesilir ya da yavaşlarsa sayfanın üstündeki çubuk bunu gösterir.","ترجمهٔ صفحه‌نمایش:":"Ekran çevirisi:","یک تب یا برنامه را به اشتراک بگذار؛ متن آن ترجمه و روی تصویر نشان داده می‌شود.":"Bir sekmeyi ya da uygulamayı paylaş; metni çevrilir ve görüntünün üzerinde gösterilir.","کارت تصویری لغت:":"Kelime kartı görseli:","یک تصویر ۱۰۸۰ در ۱۳۵۰ با زمینهٔ تیره یا روشن بساز و بفرست.":"Koyu ya da açık arka planlı, 1080 × 1350 boyutunda bir kelime görseli oluştur ve paylaş.","خروجی Word:":"Word’e aktarım:","ترجمه‌ها، نقش‌آفرینی و نگارش را به فایل Word تبدیل کن.":"Çevirileri, rol yapmayı ve yazmayı bir Word dosyasına dönüştür.","مدل پشتیبان Gemini:":"Gemini yedek modeli:","اگر مدل اصلی بعد از ۷ ثانیه جواب ندهد، مدل پشتیبان کار را ادامه می‌دهد؛ لغت و دستور زبان دیگر منتظر پیام «تقاضای زیاد» نمی‌مانند.":"Ana model 7 saniye içinde yanıt vermezse yedek model devreye girer; kelimeler ve dilbilgisi artık «yoğun talep» mesajını beklemez.","بررسی حساب در اتصال کند:":"Yavaş bağlantıda hesap kontrolü:","اگر اتصال خیلی کند باشد، بررسی ورود بعد از ۴ ثانیه تمام می‌شود و کارت «در حال بررسی» بی‌پایان نمی‌ماند.":"Bağlantı çok yavaşsa giriş kontrolü 4 saniye sonra biter ve «kontrol ediliyor» kartı sonsuza dek ekranda kalmaz."},"fr":{"تغییرات مهم Subify lite":"Les mises à jour importantes de Subify lite","نسخه جدید آماده است. اینجا مهم‌ترین قابلیت‌ها، پلتفرم‌های پشتیبانی‌شده و تغییرات ظاهری و فنی را یک‌جا می‌بینی.":"La nouvelle version est prête. Vous trouverez ici, en un seul endroit, les fonctions principales, les plateformes prises en charge et les changements d'interface et techniques.","پلتفرم‌های آموزشی":"Plateformes d’apprentissage","این صفحه فقط برای نمایش تغییرات مهم نسخه است. بعد از مطالعه، روی «متوجه شدم» بزن تا دوباره در شروع مرورگر نمایش داده نشود.":"Cette page présente les principaux changements de cette version. Après lecture, cliquez sur « Compris » pour qu’elle ne s’affiche plus au démarrage du navigateur.","متوجه شدم":"Compris","این نسخه: ۲.۹.۴۱":"Cette version : 2.9.41","صفحهٔ یادگیری:":"Page d’apprentissage :","کنترل زبان دیگر روی متن بالای صفحه نمی‌افتد و عنوان و توضیح کامل دیده می‌شوند.":"Le sélecteur de langue ne recouvre plus le texte du haut ; le titre et la description complète sont visibles.","پشتیبانی:":"Assistance :","دکمهٔ «پشتیبانی» در پنجرهٔ تازه‌ها به صفحهٔ تماس Subify می‌رود.":"Le bouton « Assistance » de la fenêtre des nouveautés ouvre désormais la page de contact de Subify.","نسخهٔ ۲.۹.۴۰":"Version 2.9.40","سری روزانه در پاپ‌آپ:":"Série quotidienne dans le popup :","پاپ‌آپ نشان می‌دهد چند روز پشت‌هم کار کرده‌ای و امروز چند دقیقه از هدفت را رفته‌ای. با زدن روی هدف می‌توانی ۵، ۱۰ یا ۲۰ دقیقه انتخاب کنی. فقط روی همین دستگاه ذخیره می‌شود.":"Le popup affiche le nombre de jours consécutifs où vous avez travaillé et les minutes du jour par rapport à votre objectif. Touchez l'objectif pour choisir 5, 10 ou 20 minutes. Il n'est enregistré que sur cet appareil.","زبان رابط کاربری در ۷ زبان:":"Interface en 7 langues :","پاپ‌آپ، تنظیمات، حساب، صفحهٔ یادگیری و صفحه‌های هوش مصنوعی به فارسی، انگلیسی، عربی، اسپانیایی، ترکی، فرانسوی و آلمانی ترجمه شده‌اند. جهت متن هم با زبان تغییر می‌کند.":"Le popup, les réglages, le compte, la page d’apprentissage et les pages IA sont traduits en persan, anglais, arabe, espagnol, turc, français et allemand. Le sens du texte change aussi avec la langue.","تنظیمات ساده‌تر:":"Réglages plus simples :","صفحهٔ تنظیمات حالا در پنج بخش است: خانه، ترجمه و دوبله، یادگیری، کلیدها و سرویس‌ها، حساب و پشتیبانی. هر چیز فقط یک جا آمده است.":"La page des réglages comporte désormais cinq sections : Accueil, Traduction et doublage, Apprentissage, Clés et services, Compte et assistance. Chaque élément n’apparaît qu’à un seul endroit.","تازه‌های این نسخه در تنظیمات:":"Nouveautés de cette version dans les réglages :","بار اول که تنظیمات را باز کنی، همین توضیح‌ها را در یک پنجرهٔ کوتاه می‌بینی. برای هر نسخه فقط یک بار نشان داده می‌شود.":"La première fois que vous ouvrez les réglages après une mise à jour, ces notes s’affichent dans une courte fenêtre. Elles n’apparaissent qu’une fois par version.","صفحه‌های هوش مصنوعی:":"Pages IA :","هدر و چیدمان گفت‌وگو، خلاصه، نقش‌آفرینی، نگارش و تمرین تلفظ با بقیهٔ صفحه‌ها یکدست شده و در زبان‌های چپ‌به‌راست و راست‌به‌چپ درست چیده می‌شوند.":"L’en-tête et la mise en page de Chat, Résumé, Jeu de rôle, Écriture et Prononciation correspondent désormais aux autres pages et sont bien alignés, dans les langues de gauche à droite comme de droite à gauche.","اعداد و متن‌ها:":"Chiffres et textes :","در زبان‌های غیرفارسی عددها لاتین نشان داده می‌شوند و متن‌های نیمه‌فارسی دیگر در رابط کاربری دیده نمی‌شوند.":"Dans les langues autres que le persan, les chiffres s’affichent en chiffres latins et le texte mêlé de persan n’apparaît plus dans l’interface.","حساب و ریست ماهانه:":"Compte et réinitialisation mensuelle :","زمان بازنشانی ماهانهٔ سهمیه با قالب تاریخ و ساعت همان زبان نشان داده می‌شود، نه عدد خام.":"L’heure de réinitialisation mensuelle du quota s’affiche au format de date et d’heure de votre langue, et non en nombre brut.","نسخهٔ ۲.۹.۳۹":"Version 2.9.39","ورود با نام کاربری و رمز:":"Connexion avec un nom d’utilisateur et un mot de passe :","حساب را با نام کاربری و رمز بساز یا وارد شو (ایمیل اختیاری است). ورود با Google، GitHub یا LinkedIn هم هست.":"Créez un compte avec un nom d’utilisateur et un mot de passe (l’e-mail est facultatif), ou connectez-vous avec Google, GitHub ou LinkedIn.","یک کلمه را بزن تا مکث شود:":"Touchez un mot pour mettre en pause :","در حالت یادگیری، زدن روی یک کلمهٔ زیرنویس ویدیو را متوقف می‌کند تا معنی‌اش را بخوانی. با بستن معنی، پخش ادامه پیدا می‌کند.":"En mode apprentissage, toucher un mot des sous-titres met la vidéo en pause pour lire son sens. Fermer le sens reprend la lecture.","کارت نقل‌قول با لینک:":"Carte de citation avec lien :","کارت نقل‌قولی که از یادگیری ساخته می‌شود حالا لینک همان لحظهٔ ویدیوی یوتیوب را دارد. لینک هنگام ساخت کارت کپی می‌شود.":"Une carte de citation créée depuis Apprentissage inclut désormais un lien vers le même moment de la vidéo YouTube. Le lien est copié à la création de la carte.","نسخهٔ ۲.۹.۳۰: یادگیری و Storyboard":"Version 2.9.30 : Apprentissage et Storyboard","بخش جدا با دو مسیر:":"Une section dédiée avec deux entrées :","زیر «یادگیری و Storyboard» توی پاپ‌آپ دو مورد هست: «یادگیری لغت» برای مرور لغت‌های ذخیره‌شده، و «Storyboard» برای دیدن صحنه‌های ترجمه‌شده. هر کدام یک توضیح کوتاه دارد و با یک کلیک باز می‌شود.":"Sous « Apprentissage et Storyboard » dans le popup, il y a deux entrées : « Apprendre les mots » pour revoir les mots enregistrés, et « Storyboard » pour voir les scènes traduites. Chacune a une courte description et s’ouvre en un clic.","همین دو ابزار از وب‌اپ هم:":"Les mêmes deux outils dans l’application web :","کارت «یادگیری و Storyboard» توی خانه و زیر بخش حساب کاربری در تنظیمات هست، پس لازم نیست حتماً از پلیر یا پاپ‌آپ بروی.":"La carte « Apprentissage et Storyboard » est sur l’accueil et sous votre compte dans les réglages ; inutile donc de passer par le lecteur ou le popup.","خروجی Anki از یادگیری لغت:":"Export Anki depuis Apprentissage :","لغت‌های ذخیره‌شده با معنی و جمله، به فایل متنی جدا می‌روند که Anki بدون تبدیل وارد می‌کند.":"Les mots enregistrés, avec leur sens et leur phrase, sont exportés dans un fichier texte qu’Anki importe sans conversion.","Storyboard با ترتیب زمان:":"Storyboard par ordre chronologique :","هر صحنه با شمارهٔ ترتیب و زمان شروع نشان داده می‌شود، جملهٔ اصلی بالا و ترجمه زیر آن می‌آید و در حالت روشن و تیره یکسان دیده می‌شود.":"Chaque scène affiche son numéro et son heure de début, la phrase originale en haut et la traduction en dessous ; le rendu est identique en mode clair et sombre.","Google Meet و زیرنویس زنده":"Google Meet et sous-titres en direct","زیرنویس در Google Meet:":"Sous-titres dans Google Meet :","وقتی دوبلهٔ زنده را در Google Meet روشن می‌کنی، زیرنویس هم نشان داده می‌شود. این قابلیت فعلاً فقط در Chrome است، چون Firefox ضبط زندهٔ صدای جلسه را ندارد.":"Quand vous activez le doublage en direct dans Google Meet, les sous-titres apparaissent aussi. Pour l’instant, cela ne fonctionne que dans Chrome, car Firefox ne peut pas capturer le son en direct d’une réunion.","توقف هم‌زمان صدا و زیرنویس:":"Audio et sous-titres s’arrêtent ensemble :","وقتی دوبلهٔ زنده را متوقف می‌کنی، صدای دوبله و زیرنویس با هم می‌ایستند و با هم ادامه پیدا می‌کنند، تا از هم جدا نشوند.":"Quand vous arrêtez le doublage en direct, l’audio doublé et les sous-titres s’arrêtent et reprennent ensemble, pour ne pas se désynchroniser.","Google Meet در فهرست پلتفرم‌ها:":"Google Meet dans la liste des plateformes :","Google Meet به پلتفرم‌های پشتیبانی‌شده اضافه شد.":"Google Meet a été ajouté aux plateformes prises en charge.","رابط کاربری و تجربهٔ کاربری":"Interface et expérience","پاپ‌آپ بدون اسکرول:":"Popup sans défilement :","همهٔ تب‌ها در ارتفاع ۶۰۰ پیکسل جا می‌شوند. دکمه‌ها حداقل ۳۲ پیکسل لمس دارند و کوچک‌ترین متن ۱۱٫۵ پیکسل است تا روی صفحه‌های کوچک هم خوانا باشد.":"Tous les onglets tiennent dans un popup de 600 pixels de haut. Les boutons ont une zone tactile d’au moins 32 pixels et le plus petit texte fait 11,5 pixels, pour rester lisible sur les petits écrans.","بخش‌های جمع‌شونده:":"Sections repliables :","«یادگیری و Storyboard» و «تنظیمات پیشرفته» جمع می‌شوند تا پاپ‌آپ شلوغ نشود.":"« Apprentissage et Storyboard » et « Réglages avancés » se replient pour garder le popup clair.","حالت روشن و تیره:":"Mode clair et sombre :","پاپ‌آپ، تنظیمات، صفحهٔ یادگیری و Storyboard هر دو حالت را دارند و رنگ‌ها در هر دو یکدست هستند.":"Le popup, les réglages, la page Apprentissage et le Storyboard prennent en charge les deux modes, avec des couleurs cohérentes.","توضیح بالای هر صفحه:":"Une courte note en haut de chaque page :","صفحهٔ یادگیری و Storyboard در بالا می‌گوید هر بخش چه کاری انجام می‌دهد و چطور شروع کنی.":"Les pages Apprentissage et Storyboard expliquent en haut ce que fait chaque partie et comment commencer.","ترجمه و هوش مصنوعی":"Traduction et IA","چت، نقش‌آفرینی و نگارش بدون ورود باز هستند:":"Chat, jeu de rôle et écriture s’ouvrent sans connexion :","این سه بخش دیگر پشت صفحهٔ ورود قرار نمی‌گیرند.":"Ces trois espaces ne sont plus derrière l’écran de connexion.","کلید خودت، هر سرویس:":"Votre propre clé, tous les services :","چت، نقش‌آفرینی و نگارش با کلید Gemini، OpenRouter، OpenAI یا سرویس اختصاصی خودت کار می‌کنند. دوبلهٔ زنده فقط با Gemini کار می‌کند.":"Le chat, le jeu de rôle et l’écriture fonctionnent avec votre propre clé Gemini, OpenRouter, OpenAI ou d’un service personnalisé. Le doublage en direct ne fonctionne qu’avec Gemini.","ترجمهٔ کل صفحه:":"Traduction de la page entière :","همهٔ متن قابل‌دیدن صفحه ترجمه می‌شود، نه فقط بخش اول. ترجمهٔ هر آدرس روی همان مرورگر ذخیره می‌شود تا دوباره لازم نباشد از نو ترجمه شود.":"Tout le texte visible de la page est traduit, pas seulement la première partie. La traduction de chaque adresse est conservée dans le même navigateur, inutile donc de la refaire.","ده استفادهٔ رایگان:":"Dix utilisations gratuites :","ترجمه، دوبله و ترجمهٔ صفحه تا ده بار بدون ورود. هر ویدیو فقط یک بار حساب می‌شود، حتی اگر هم ترجمه و هم دوبله شود.":"Traduction, doublage et traduction de page, jusqu’à dix fois sans connexion. Chaque vidéo ne compte qu’une fois, même si vous la traduisez et la doublez.","وب‌اپلیکیشن":"Application web","شروع سریع:":"Démarrage rapide :","متن یا فایل زیرنویس را همان‌جا بگذار؛ ترجمه همان لحظه شروع می‌شود.":"Collez le texte des sous-titres ou déposez le fichier ici, et la traduction démarre aussitôt.","کار بدون اینترنت:":"Fonctionne hors ligne :","بعد از اولین باز شدن، برنامه بدون اتصال هم باز می‌شود و لغت‌ها و Storyboard روی دستگاهت می‌مانند. وقتی اینترنت قطع یا کند می‌شود، نوار بالای صفحه این را نشان می‌دهد.":"Après la première visite, l’application s’ouvre sans connexion, et vos mots et le Storyboard restent sur votre appareil. Quand la connexion coupe ou ralentit, une barre en haut l’indique.","ترجمهٔ صفحه‌نمایش:":"Traduction de l’écran :","یک تب یا برنامه را به اشتراک بگذار؛ متن آن ترجمه و روی تصویر نشان داده می‌شود.":"Partagez un onglet ou une application ; son texte est traduit et affiché par-dessus l’image.","کارت تصویری لغت:":"Image de carte de mot :","یک تصویر ۱۰۸۰ در ۱۳۵۰ با زمینهٔ تیره یا روشن بساز و بفرست.":"Créez une image de 1080 × 1350 d’un mot, sur fond sombre ou clair, puis partagez-la.","خروجی Word:":"Export Word :","ترجمه‌ها، نقش‌آفرینی و نگارش را به فایل Word تبدیل کن.":"Transformez traductions, jeux de rôle et écriture en fichier Word.","مدل پشتیبان Gemini:":"Modèle de secours Gemini :","اگر مدل اصلی بعد از ۷ ثانیه جواب ندهد، مدل پشتیبان کار را ادامه می‌دهد؛ لغت و دستور زبان دیگر منتظر پیام «تقاضای زیاد» نمی‌مانند.":"Si le modèle principal ne répond pas en 7 secondes, le modèle de secours prend le relais ; les mots et la grammaire n’attendent plus le message « forte demande ».","بررسی حساب در اتصال کند:":"Vérification du compte sur connexion lente :","اگر اتصال خیلی کند باشد، بررسی ورود بعد از ۴ ثانیه تمام می‌شود و کارت «در حال بررسی» بی‌پایان نمی‌ماند.":"Si la connexion est très lente, la vérification de connexion se termine après 4 secondes, et la carte « vérification » ne reste pas indéfiniment affichée."},"de":{"تغییرات مهم Subify lite":"Wichtige Subify lite-Neuerungen","نسخه جدید آماده است. اینجا مهم‌ترین قابلیت‌ها، پلتفرم‌های پشتیبانی‌شده و تغییرات ظاهری و فنی را یک‌جا می‌بینی.":"Die neue Version ist fertig. Hier siehst du die wichtigsten Funktionen, unterstützten Plattformen sowie Änderungen an Oberfläche und Technik auf einen Blick.","پلتفرم‌های آموزشی":"Lernplattformen","این صفحه فقط برای نمایش تغییرات مهم نسخه است. بعد از مطالعه، روی «متوجه شدم» بزن تا دوباره در شروع مرورگر نمایش داده نشود.":"Diese Seite zeigt die wichtigsten Änderungen dieser Version. Klicke nach dem Lesen auf „Verstanden“, damit sie beim Browserstart nicht mehr erscheint.","متوجه شدم":"Verstanden","این نسخه: ۲.۹.۴۱":"Diese Version: 2.9.41","صفحهٔ یادگیری:":"Lernseite:","کنترل زبان دیگر روی متن بالای صفحه نمی‌افتد و عنوان و توضیح کامل دیده می‌شوند.":"Die Sprachauswahl überdeckt den Text oben nicht mehr; Titel und Beschreibung sind vollständig sichtbar.","پشتیبانی:":"Support:","دکمهٔ «پشتیبانی» در پنجرهٔ تازه‌ها به صفحهٔ تماس Subify می‌رود.":"Die Schaltfläche „Support“ im Fenster „Neuerungen“ öffnet jetzt die Kontaktseite von Subify.","نسخهٔ ۲.۹.۴۰":"Version 2.9.40","سری روزانه در پاپ‌آپ:":"Tagesserie im Popup:","پاپ‌آپ نشان می‌دهد چند روز پشت‌هم کار کرده‌ای و امروز چند دقیقه از هدفت را رفته‌ای. با زدن روی هدف می‌توانی ۵، ۱۰ یا ۲۰ دقیقه انتخاب کنی. فقط روی همین دستگاه ذخیره می‌شود.":"Das Popup zeigt, an wie vielen Tagen in Folge du gearbeitet hast und wie viele Minuten du heute im Vergleich zu deinem Ziel erreicht hast. Tippe auf das Ziel, um 5, 10 oder 20 Minuten zu wählen. Es wird nur auf diesem Gerät gespeichert.","زبان رابط کاربری در ۷ زبان:":"Oberfläche in 7 Sprachen:","پاپ‌آپ، تنظیمات، حساب، صفحهٔ یادگیری و صفحه‌های هوش مصنوعی به فارسی، انگلیسی، عربی، اسپانیایی، ترکی، فرانسوی و آلمانی ترجمه شده‌اند. جهت متن هم با زبان تغییر می‌کند.":"Popup, Einstellungen, Konto, Lernseite und KI-Seiten sind auf Persisch, Englisch, Arabisch, Spanisch, Türkisch, Französisch und Deutsch übersetzt. Auch die Textrichtung wechselt mit der Sprache.","تنظیمات ساده‌تر:":"Einfachere Einstellungen:","صفحهٔ تنظیمات حالا در پنج بخش است: خانه، ترجمه و دوبله، یادگیری، کلیدها و سرویس‌ها، حساب و پشتیبانی. هر چیز فقط یک جا آمده است.":"Die Einstellungen haben jetzt fünf Bereiche: Start, Übersetzung und Synchronisation, Lernen, Schlüssel und Dienste sowie Konto und Support. Jede Funktion steht nur an einer Stelle.","تازه‌های این نسخه در تنظیمات:":"Neuerungen dieser Version in den Einstellungen:","بار اول که تنظیمات را باز کنی، همین توضیح‌ها را در یک پنجرهٔ کوتاه می‌بینی. برای هر نسخه فقط یک بار نشان داده می‌شود.":"Wenn du die Einstellungen nach einem Update zum ersten Mal öffnest, siehst du diese Hinweise in einem kurzen Fenster. Es erscheint einmal pro Version.","صفحه‌های هوش مصنوعی:":"KI-Seiten:","هدر و چیدمان گفت‌وگو، خلاصه، نقش‌آفرینی، نگارش و تمرین تلفظ با بقیهٔ صفحه‌ها یکدست شده و در زبان‌های چپ‌به‌راست و راست‌به‌چپ درست چیده می‌شوند.":"Kopfzeile und Aufbau von Chat, Zusammenfassung, Rollenspiel, Schreiben und Aussprache entsprechen jetzt den anderen Seiten und sind in Links-nach-rechts- und Rechts-nach-links-Sprachen richtig ausgerichtet.","اعداد و متن‌ها:":"Zahlen und Texte:","در زبان‌های غیرفارسی عددها لاتین نشان داده می‌شوند و متن‌های نیمه‌فارسی دیگر در رابط کاربری دیده نمی‌شوند.":"In nicht-persischen Sprachen werden Zahlen mit lateinischen Ziffern angezeigt, und gemischter persischer Text erscheint in der Oberfläche nicht mehr.","حساب و ریست ماهانه:":"Konto und monatlicher Reset:","زمان بازنشانی ماهانهٔ سهمیه با قالب تاریخ و ساعت همان زبان نشان داده می‌شود، نه عدد خام.":"Die Uhrzeit des monatlichen Kontingent-Resets wird im Datums- und Zeitformat deiner Sprache angezeigt, nicht als Rohzahl.","نسخهٔ ۲.۹.۳۹":"Version 2.9.39","ورود با نام کاربری و رمز:":"Anmeldung mit Benutzername und Passwort:","حساب را با نام کاربری و رمز بساز یا وارد شو (ایمیل اختیاری است). ورود با Google، GitHub یا LinkedIn هم هست.":"Erstelle ein Konto mit Benutzername und Passwort (E-Mail ist optional) oder melde dich mit Google, GitHub oder LinkedIn an.","یک کلمه را بزن تا مکث شود:":"Tippe auf ein Wort, um zu pausieren:","در حالت یادگیری، زدن روی یک کلمهٔ زیرنویس ویدیو را متوقف می‌کند تا معنی‌اش را بخوانی. با بستن معنی، پخش ادامه پیدا می‌کند.":"Im Lernmodus pausiert ein Tipp auf ein Untertitelwort das Video, damit du die Bedeutung lesen kannst. Wenn du sie schließt, läuft das Video weiter.","کارت نقل‌قول با لینک:":"Zitatkarte mit Link:","کارت نقل‌قولی که از یادگیری ساخته می‌شود حالا لینک همان لحظهٔ ویدیوی یوتیوب را دارد. لینک هنگام ساخت کارت کپی می‌شود.":"Eine Zitatkarte aus dem Lernbereich enthält jetzt einen Link zu genau dieser Stelle im YouTube-Video. Der Link wird beim Erstellen der Karte kopiert.","نسخهٔ ۲.۹.۳۰: یادگیری و Storyboard":"Version 2.9.30: Lernen und Storyboard","بخش جدا با دو مسیر:":"Ein eigener Bereich mit zwei Einträgen:","زیر «یادگیری و Storyboard» توی پاپ‌آپ دو مورد هست: «یادگیری لغت» برای مرور لغت‌های ذخیره‌شده، و «Storyboard» برای دیدن صحنه‌های ترجمه‌شده. هر کدام یک توضیح کوتاه دارد و با یک کلیک باز می‌شود.":"Unter „Lernen und Storyboard“ im Popup gibt es zwei Einträge: „Wörter lernen“ zum Wiederholen gespeicherter Wörter und „Storyboard“ zum Anzeigen übersetzter Szenen. Jeder hat einen kurzen Hinweis und öffnet sich mit einem Klick.","همین دو ابزار از وب‌اپ هم:":"Dieselben zwei Werkzeuge in der Web-App:","کارت «یادگیری و Storyboard» توی خانه و زیر بخش حساب کاربری در تنظیمات هست، پس لازم نیست حتماً از پلیر یا پاپ‌آپ بروی.":"Die Karte „Lernen und Storyboard“ findest du auf der Startseite und unter deinem Konto in den Einstellungen, du musst also nicht erst den Player oder das Popup öffnen.","خروجی Anki از یادگیری لغت:":"Anki-Export aus dem Lernbereich:","لغت‌های ذخیره‌شده با معنی و جمله، به فایل متنی جدا می‌روند که Anki بدون تبدیل وارد می‌کند.":"Gespeicherte Wörter mit Bedeutung und Satz werden in eine separate Textdatei exportiert, die Anki ohne Umwandlung importiert.","Storyboard با ترتیب زمان:":"Storyboard in zeitlicher Reihenfolge:","هر صحنه با شمارهٔ ترتیب و زمان شروع نشان داده می‌شود، جملهٔ اصلی بالا و ترجمه زیر آن می‌آید و در حالت روشن و تیره یکسان دیده می‌شود.":"Jede Szene zeigt ihre Nummer und Startzeit, oben den Originalsatz und darunter die Übersetzung; im hellen und dunklen Modus sieht sie gleich aus.","Google Meet و زیرنویس زنده":"Google Meet und Live-Untertitel","زیرنویس در Google Meet:":"Untertitel in Google Meet:","وقتی دوبلهٔ زنده را در Google Meet روشن می‌کنی، زیرنویس هم نشان داده می‌شود. این قابلیت فعلاً فقط در Chrome است، چون Firefox ضبط زندهٔ صدای جلسه را ندارد.":"Wenn du die Live-Synchronisation in Google Meet einschaltest, werden auch Untertitel angezeigt. Das funktioniert vorerst nur in Chrome, weil Firefox den Live-Ton einer Besprechung nicht erfassen kann.","توقف هم‌زمان صدا و زیرنویس:":"Ton und Untertitel stoppen gemeinsam:","وقتی دوبلهٔ زنده را متوقف می‌کنی، صدای دوبله و زیرنویس با هم می‌ایستند و با هم ادامه پیدا می‌کنند، تا از هم جدا نشوند.":"Wenn du die Live-Synchronisation stoppst, halten Synchronton und Untertitel gemeinsam an und laufen gemeinsam weiter, damit sie nicht auseinanderlaufen.","Google Meet در فهرست پلتفرم‌ها:":"Google Meet in der Plattformliste:","Google Meet به پلتفرم‌های پشتیبانی‌شده اضافه شد.":"Google Meet wurde zu den unterstützten Plattformen hinzugefügt.","رابط کاربری و تجربهٔ کاربری":"Oberfläche und Bedienung","پاپ‌آپ بدون اسکرول:":"Popup ohne Scrollen:","همهٔ تب‌ها در ارتفاع ۶۰۰ پیکسل جا می‌شوند. دکمه‌ها حداقل ۳۲ پیکسل لمس دارند و کوچک‌ترین متن ۱۱٫۵ پیکسل است تا روی صفحه‌های کوچک هم خوانا باشد.":"Alle Tabs passen in ein 600 Pixel hohes Popup. Schaltflächen haben einen Berührungsbereich von mindestens 32 Pixeln, und der kleinste Text hat 11,5 Pixel, damit er auch auf kleinen Bildschirmen lesbar bleibt.","بخش‌های جمع‌شونده:":"Einklappbare Bereiche:","«یادگیری و Storyboard» و «تنظیمات پیشرفته» جمع می‌شوند تا پاپ‌آپ شلوغ نشود.":"„Lernen und Storyboard“ und „Erweiterte Einstellungen“ lassen sich einklappen, damit das Popup übersichtlich bleibt.","حالت روشن و تیره:":"Heller und dunkler Modus:","پاپ‌آپ، تنظیمات، صفحهٔ یادگیری و Storyboard هر دو حالت را دارند و رنگ‌ها در هر دو یکدست هستند.":"Popup, Einstellungen, Lernseite und Storyboard unterstützen beide Modi, mit einheitlichen Farben in jedem.","توضیح بالای هر صفحه:":"Ein kurzer Hinweis oben auf jeder Seite:","صفحهٔ یادگیری و Storyboard در بالا می‌گوید هر بخش چه کاری انجام می‌دهد و چطور شروع کنی.":"Die Seiten Lernen und Storyboard erklären oben, was jeder Bereich macht und wie man anfängt.","ترجمه و هوش مصنوعی":"Übersetzung und KI","چت، نقش‌آفرینی و نگارش بدون ورود باز هستند:":"Chat, Rollenspiel und Schreiben sind ohne Anmeldung offen:","این سه بخش دیگر پشت صفحهٔ ورود قرار نمی‌گیرند.":"Diese drei Bereiche liegen nicht mehr hinter dem Anmeldebildschirm.","کلید خودت، هر سرویس:":"Dein eigener Schlüssel, jeder Dienst:","چت، نقش‌آفرینی و نگارش با کلید Gemini، OpenRouter، OpenAI یا سرویس اختصاصی خودت کار می‌کنند. دوبلهٔ زنده فقط با Gemini کار می‌کند.":"Chat, Rollenspiel und Schreiben funktionieren mit deinem eigenen Schlüssel von Gemini, OpenRouter, OpenAI oder einem eigenen Dienst. Die Live-Synchronisation funktioniert nur mit Gemini.","ترجمهٔ کل صفحه:":"Ganze Seite übersetzen:","همهٔ متن قابل‌دیدن صفحه ترجمه می‌شود، نه فقط بخش اول. ترجمهٔ هر آدرس روی همان مرورگر ذخیره می‌شود تا دوباره لازم نباشد از نو ترجمه شود.":"Der gesamte sichtbare Text der Seite wird übersetzt, nicht nur der erste Teil. Die Übersetzung jeder Adresse wird im selben Browser gespeichert, sodass sie nicht erneut übersetzt werden muss.","ده استفادهٔ رایگان:":"Zehn kostenlose Nutzungen:","ترجمه، دوبله و ترجمهٔ صفحه تا ده بار بدون ورود. هر ویدیو فقط یک بار حساب می‌شود، حتی اگر هم ترجمه و هم دوبله شود.":"Übersetzung, Synchronisation und Seitenübersetzung, bis zu zehnmal ohne Anmeldung. Jedes Video zählt einmal, auch wenn du es übersetzt und synchronisierst.","وب‌اپلیکیشن":"Web-App","شروع سریع:":"Schnellstart:","متن یا فایل زیرنویس را همان‌جا بگذار؛ ترجمه همان لحظه شروع می‌شود.":"Füge den Untertiteltext ein oder ziehe die Datei hierher, und die Übersetzung startet sofort.","کار بدون اینترنت:":"Funktioniert offline:","بعد از اولین باز شدن، برنامه بدون اتصال هم باز می‌شود و لغت‌ها و Storyboard روی دستگاهت می‌مانند. وقتی اینترنت قطع یا کند می‌شود، نوار بالای صفحه این را نشان می‌دهد.":"Nach dem ersten Besuch öffnet sich die App auch ohne Verbindung, und deine Wörter und das Storyboard bleiben auf deinem Gerät. Bricht die Verbindung ab oder wird sie langsam, zeigt eine Leiste oben das an.","ترجمهٔ صفحه‌نمایش:":"Bildschirmübersetzung:","یک تب یا برنامه را به اشتراک بگذار؛ متن آن ترجمه و روی تصویر نشان داده می‌شود.":"Teile einen Tab oder eine App; ihr Text wird übersetzt und über dem Bild angezeigt.","کارت تصویری لغت:":"Wortkarten-Bild:","یک تصویر ۱۰۸۰ در ۱۳۵۰ با زمینهٔ تیره یا روشن بساز و بفرست.":"Erstelle ein 1080 × 1350 großes Bild eines Wortes mit dunklem oder hellem Hintergrund und teile es.","خروجی Word:":"Word-Export:","ترجمه‌ها، نقش‌آفرینی و نگارش را به فایل Word تبدیل کن.":"Wandle Übersetzungen, Rollenspiele und Texte in eine Word-Datei um.","مدل پشتیبان Gemini:":"Gemini-Ersatzmodell:","اگر مدل اصلی بعد از ۷ ثانیه جواب ندهد، مدل پشتیبان کار را ادامه می‌دهد؛ لغت و دستور زبان دیگر منتظر پیام «تقاضای زیاد» نمی‌مانند.":"Antwortet das Hauptmodell nicht innerhalb von 7 Sekunden, übernimmt das Ersatzmodell; Wörter und Grammatik warten nicht mehr auf die Meldung „hohe Nachfrage“.","بررسی حساب در اتصال کند:":"Kontoprüfung bei langsamer Verbindung:","اگر اتصال خیلی کند باشد، بررسی ورود بعد از ۴ ثانیه تمام می‌شود و کارت «در حال بررسی» بی‌پایان نمی‌ماند.":"Ist die Verbindung sehr langsam, endet die Anmeldeprüfung nach 4 Sekunden, und die Karte „wird geprüft“ bleibt nicht endlos stehen."}});
